(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0017.js"] = [{"id":"poem-6fb664e296ae5d316ddac815","title":"古大梁行","author":"高适","dynasty":"唐","verses":["古城莽苍饶荆榛，驱马荒城愁杀人。","魏王宫观尽禾黍，信陵宾客随灰尘。","忆昨雄都旧朝市，轩车照耀歌钟起。","军容带甲三十万，国步连营一千里。","全盛须臾那可论，高台曲池无复存。","遗墟但见狐狸迹，古地空余草木根。","暮天摇落伤怀抱，倚劒悲歌对秋草。","侠客犹传朱亥名，行人尚识夷门道。","白璧黄金万户侯，宝刀骏马填山丘。","年代凄凉不可问，往来唯有水东流。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-5e31820a-bcc7-4bb7-b173-ab69e432e45c","tags":["隋・唐・五代","咏史怀古"]},{"id":"poem-6fb8c525ca03d23b87411ecb","title":"挽郡博士待班刘公歌","author":"王柏","dynasty":"宋","verses":["东风变九野，万物负生意。","素𫖒何栾栾，清血洒幽隧。","猗欤静寿翁，归全可无愧。","人生托溟涬，消息同一气。","过化来者续，自昔叹川逝。","温温夙好修，甄陶瑚琏器。","凝乎觚自度，澹乎靓且邃。","诗书以为粮，忠信以为饎。","人皆崇荣途，公独徐揽辔。","三转坐臯比，五鹗争自致。","上培德谊种，下开文字瑞。","一子通金闺，一子需大对。","衣冠绘庆图，岂料造物忌。","学校失师模，乡闾思善类。","梅花已流水，草木谁臭味。","惟有笃厚心，叮咛期嗣世。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-211a2e2a-9b3f-47ed-9ead-b404f07a0dc1","tags":[]},{"id":"poem-6fba9f653bab6cd6c3f2e40a","title":"菩萨蛮·问君何事轻离别","author":"纳兰性德","dynasty":"清","verses":["问君何事轻离别，一年能几团圆月。","杨柳乍如丝。","故园春尽时。","春归归不得，两桨松花隔。","旧事逐寒潮，啼鹃恨未消。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-6","tags":[]},{"id":"poem-6fc1a2e2f3b8340586cd32d0","title":"醉花阴·东皇已有来归耗","author":"葛胜仲","dynasty":"宋","verses":["东皇已有来归耗。","十里青山道。","冻蘖万株梅，一夜妆成，似趁鸣鸡早。","年时清赏曾同到。","先仗游蜂报。","抖擞旧心情，一笑酬春，不羡和羹诏。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-30","tags":[]},{"id":"poem-6fc505e500cbcd97929916a0","title":"西湖戏书二首  其一","author":"梅窗","dynasty":"宋","verses":["蜿蜿翠麓秋烟涨，滟滟金波夜月澄。","樽酒具时随兴遣，景多逢处曲栏凭。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-f5fdfae4-eae6-4644-a969-36d54ab43e28","tags":["西湖"]},{"id":"poem-6fc5a4d30bae970e8796cccb","title":"宋城道中逢王直方八韵","author":"张祜","dynasty":"唐","verses":["二年离子载，发迹自江南。","马上行寻度，途中语再三。","始因穷去魏，河北战方酣。","后以文投许，淮西难未戡。","谪官逢李涉，狂客见刘弇。","失意怜初话，多端耻旧谙。","茶风无奈笔，酒秃不胜簪。","几郁胸中恨，聊当遂剧谈。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-e5083d11-7f30-4681-9c30-f98524b56778","tags":[]},{"id":"poem-6fd4e21c8edf2d3d8939b59d","title":"又和惜春谣","author":"司马光","dynasty":"宋","verses":["朝来风雨歇，春意漠然收。","去我不辞诀，凭谁能借留。","杓星渐西转，洛水自东流。","曲渚撤华幄，芳园罢彩毬。","雉鸣坵麦秀，蚕起野桑柔。","乱絮天涯满，晴阳草际浮。","已嗟心绪减，况复鬓丝稠。","赖听新翻曲，非为负胜游。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-2e3db9b7-dd35-481b-85df-66d5212c77dc","tags":[]},{"id":"poem-6fdd4f0808c4183a29dfa344","title":"春晚","author":"崔道融","dynasty":"唐","verses":["三月寒食时，日色浓于酒。","落尽墙头花，莺声隔原柳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-a1951ae4-c079-47e1-90e9-fc5fe1c7c98e","tags":[]},{"id":"poem-6ff32aed97530b9200055351","title":"净巾石","author":"陈岩","dynasty":"宋","verses":["炯炯豁开明镜台，是中无处著尘埃。","平生心地常如此，何暇频频拂拭来。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-b8d3dbea-2c97-4309-ab34-e7b282c0c40c","tags":[]},{"id":"poem-6ffd020fbce3a4457b9bfaae","title":"乌栖曲","author":"李端","dynasty":"唐","verses":["白马逐朱车，黄昏入狭斜。","狭斜柳树乌争宿，争枝未得飞上屋。","东房少妇壻从军，每听乌啼知夜分。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-29349510-7c20-4105-b50d-258ce53a8523","tags":[]},{"id":"poem-6ffde0953963f723b9a75d67","title":"坐黄冈广福禅房","author":"郭昂","dynasty":"宋","verses":["爱此禅栖静，清凉境自偏。","诧人拳怪树，留客笑幽莲。","草暖蛙喧夏，林昏鸟梦烟。","风尘吾未免，兀坐愧安禅。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-838829a5-a0b3-4191-9f81-64f9f79cebd1","tags":[]},{"id":"poem-7007fe2fcf99ddbf119a13cf","title":"玉楼春·春风只在园西畔","author":"严仁","dynasty":"宋","verses":["春风只在园西畔。","荠菜花繁胡蝶乱。","冰池晴绿照还空，香径落红吹已断。","意长翻恨游丝短。","尽日相思罗带缓。","宝奁明月不欺人，明日归来君试看。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-51","tags":["宋词三百首"]},{"id":"poem-701065cb6bc139d99a491e10","title":"晚秋赠张折冲","author":"薛业","dynasty":"唐","verses":["都尉今无事，时清但闭关。","夜霜戎马瘦，秋草射堂闲。","位以穿杨得，名因折桂还。","冯唐真不遇，叹息鬓毛斑。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-213e4cab-d7a1-4e33-a8c9-c20c50226dd8","tags":[]},{"id":"poem-7010df49ffa3ec202e72a380","title":"傅家林","author":"释居简","dynasty":"宋","verses":["樵斧响晴雷，平林顷刻摧。","兔亡三穴徙，猿吊一枝哀。","桑梓思前辈，松杉惜上林。","养林如养德，万木盍重栽。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-90be5793-82fe-4689-b810-b30bf0f1178e","tags":[]},{"id":"poem-7013e1a3c314ad08f9d6a277","title":"落第归乡留别长安主人","author":"豆卢复","dynasty":"唐","verses":["客里愁多不记春，闻莺始叹柳条新。","年年下第东归去，羞见长安旧主人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-215caa5f-74fc-4e81-af61-b8ba6c9a9ff0","tags":[]},{"id":"poem-701cf32880c7656778478b5f","title":"杨柳枝寿杯词十八首 十七","author":"司空图","dynasty":"唐","verses":["大堤时节近清明，霞衬烟笼遶郡城。","好是梨花相映处，更胜松雪日初晴。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-13884152-b9e9-40c7-abb8-2540daa9747e","tags":[]},{"id":"poem-701ece5163a758dc386ddcd9","title":"霜天晓角","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["(小生，杂从上)黄堂佐政齐黎庶，肯将清似月扬辉，如渊彻底，愿效汉循良吏。","勤簿书，门馆无私，日以刑名为事。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8299","tags":[]},{"id":"poem-70211ccc8568c2104f812510","title":"葛仙迁居图","author":"释居简","dynasty":"宋","verses":["欲问丹砂不定居，绝怜岣嵝令君疎。","弗教鸡犬蜚腾去，犹看随行挂角书。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-4639973b-33b0-45b6-9951-ed4e20f236c6","tags":[]},{"id":"poem-7021ab88c465a5bf095d545d","title":"霜天晓角","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["悄然魂似飞，料应不久矣。","纵然抬头强起，(介)形衰倦，怎支持？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5102","tags":[]},{"id":"poem-703ea2e2b800e7680b1495f9","title":"石刻诗","author":"陈抟","dynasty":"宋","verses":["我谓浮荣真是幻，醉来舍辔谒高公。","因聆玄论冥冥理，转觉尘寰一梦中。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-6e00a6d9-8d34-4fd5-8c38-69f96f251404","tags":[]},{"id":"poem-70529462116f6e075e056f97","title":"水调歌头·天地有英气","author":"熊以宁","dynasty":"宋","verses":["天地有英气，锺秀在人间。","流虹甫近华旦，维岳预生贤。","千载明良会遇，三世勋庸忠烈，谁得似家传。","高论排风俗，抗志遏狂澜。","记年时，胡尘外，拥朱幡。","洪枢紫府功业，指日复青毡。","拭目泥封飞下，趁取梅花消息，去去簉朝班。","骨相元不老，何必颂南山。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-309","tags":[]},{"id":"poem-7056082d2a14ff2486c6b07a","title":"过香积寺","author":"王维","dynasty":"唐","verses":["不知香积寺，数里入云峰。","古木无人迳，深山何处钟。","泉声咽危石，日色冷青松。","薄暮空潭曲，安禅制毒龙。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-e4354c00-c83e-43da-9341-7007889dd625","tags":["唐诗三百首","写景","五言律诗"]},{"id":"poem-705c156c3e5369977cc3e01a","title":"修竹百竿才欣种植佳篇五首旋辱咏歌若无还答之言是阙唱酬之礼恭依来韵以导鄙怀调下才卑岂逃嗤诮  其一","author":"李昉","dynasty":"宋","verses":["谩栽花卉满朱栏，争似疏篁种百竿。","长爱枕前闻淅沥，乍欣窗外见檀栾。","春来莫重和烟翠，岁晚应须带雪看。","我得此君添一友，时时相对列杯盘。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-28a085de-ef77-4105-bda7-b43d69213e3f","tags":[]},{"id":"poem-7060b23bf454ed16f3d9ab2b","title":"念奴娇·霜威凄紧","author":"向","dynasty":"宋","verses":["霜威凄紧，政悲风摇落，千山群木。","十里清香方盛赏，岩桂娇黄姹绿。","九畹衰丛，东篱落蕊，到此成粗俗。","孤标高远，淡然还媚幽独。","憔悴诗老多情，问佳人底事，幽居空谷。","日暮天寒垂翠袖，愁倚萧萧修竹。","林下神情，月边风露，不向雕栏曲。","殷勤惟有，篆烟留得馀馥。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-181","tags":[]},{"id":"poem-70669ac9acf2e98ea5a8b550","title":"送人归夏口","author":"贯休","dynasty":"唐","verses":["鴈鴈叶纷纷，行人岂易闻。","千山与万水，何处更逢君？","貌不长如玉，人生祗似云。","倘经三祖寺，一为礼龛坟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-69b92e14-b8e7-450c-b2ad-6dc1eb640c6e","tags":[]},{"id":"poem-70733e6df77ca0dd7e8ad258","title":"和韦相公话婺州陈事","author":"贯休","dynasty":"唐","verses":["昔事堪惆怅，谈玄爱白牛。","千场花下醉，一片梦中游。","耕避初平石，烧残沈约楼。","无因更重到，且副济川舟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-42388f80-e8cb-49c8-a042-7e60afbf8fe3","tags":[]},{"id":"poem-7073d6da60df76a19a8799ad","title":"峡哀 二","author":"孟郊","dynasty":"唐","verses":["上天下天水，出地入地舟。","石劒相劈斫，石波怒蛟虬。","花木叠宿春，风飙凝古秋。","幽怪窟穴语，飞闻肸蚃流。","沈哀日已深，衔诉将何求。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-6c740e0f-b75f-4d19-abee-2c5a51e7f96f","tags":[]},{"id":"poem-70839d6dd0b23dd7536df1be","title":"惜誓","author":"贾谊","dynasty":"汉","verses":["惜余年老而日衰兮，岁忽忽而不反。","登苍天而高举兮，历众山而日远。","观江河之纡曲兮，离四海之沾濡。","攀北极而一息兮，吸沆瀣以充虚。","飞朱鸟使先驱兮，驾太一之象舆。","苍龙蚴虬于左骖兮，白虎骋而为右𬴂。","建日月以为盖兮，载玉女于后车。","驰骛于杳冥之中兮，休息虖昆仑之墟。","乐穷极而不厌兮，愿从容虖神明。","涉丹水而驰骋兮，右大夏之遗风。","黄鹄之一举兮，知山川之纡曲。","再举兮，睹天地之圜方。","临中国之众人兮，讬回飙乎尚羊。","乃至少原之野兮，赤松、王乔皆在旁。","二子拥瑟而调均兮，余因称乎清商。","澹然而自乐兮，吸众气而翱翔。","念我长生而久仙兮，不如反余之故乡。","黄鹄后时而寄处兮，鸱枭群而制之。","神龙失水而陆居兮，为蝼蚁之所裁。","夫黄鹄神龙犹如此兮，况贤者之逢乱世哉。","寿冉冉而日衰兮，固儃回而不息。","俗流从而不止兮，众枉聚而矫直。","或偷合而苟进兮，或隐居而深藏。","苦称量之不审兮，同权概而就衡。","或推迻而苟容兮，或直言之谔謣。","伤诚是之不察兮，并纫茅丝以为索。","方世俗之幽昏兮，眩白黑之美恶。","放山渊之龟玉兮，相与贵夫砾石。","梅伯数谏而至醢兮，来革顺志而用国。","悲仁人之尽节兮，反为小人之所贼。","比干忠谏而剖心兮，箕子被发而佯狂。","水背流而源竭兮，木去根而不长。","非重躯以虑难兮，惜伤身之无功。","已矣哉！独不见夫鸾凤之高翔兮，乃集大皇之野。","循四极而回周兮，见盛德而后下。","彼圣人之神德兮，远浊世而自藏。","使麒麟可得羁而系兮，又何以异虖犬羊？"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-28","tags":[]},{"id":"poem-708dd34464e5111996c7b1f3","title":"酬尧夫招看牡丹  其一","author":"司马光","dynasty":"宋","verses":["君家牡丹深浅红，二十四枝为一丛。","不唯春光占七八，才华自是诗人雄。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-be28cde8-b181-4f53-8d9d-187b7f88f9cb","tags":[]},{"id":"poem-709241a3632bc8e9ee38c7ad","title":"郊庙歌辞 梁太庙乐舞辞 登歌","author":"不详","dynasty":"唐","verses":["于赫我皇，建中立极。","动以武功，静以文德。","昭事上帝，欢心万国。","大报严禋，四海述职。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-630ab837-d414-4cce-bf80-bc615a6c15fd","tags":[]},{"id":"poem-709c9012de926684d98fb498","title":"蜀道难","author":"李白","dynasty":"唐","verses":["噫吁戏！危乎高哉！蜀道之难难于上青天！蚕丛及鱼凫，开国何茫然。","尔来四万八千岁，不与秦塞通人烟。","西当太白有鸟道，可以横绝峨眉巅。","地崩山摧壮士死，然后天梯石栈相钩连。","上有六龙回日之高标，下有冲波逆折之回川。","黄鹤之飞尚不得过，猨猱欲度愁攀援。","青泥何盘盘，百步九折萦岩峦。","扪参历井仰胁息，以手抚膺坐长叹。","问君西游何时还？畏途巉岩不可攀。","但见悲鸟号古木，雄飞雌从绕林间。","又闻子规啼夜月，愁空山，蜀道之难难于上青天，使人听此凋朱颜。","连峰去天不盈尺，枯松倒挂倚绝壁。","飞湍瀑流争喧豗，砅厓转石万壑雷。","其险也如此，嗟尔远道之人胡为乎来哉！劒阁峥嵘而崔嵬，一夫当关，万夫莫开。","所守或匪亲，化为狼与豺。","朝避猛虎，夕避长蛇。","磨牙吮血，杀人如麻。","锦城虽云乐，不如早还家。","蜀道之难难于上青天，侧身西望长咨嗟。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-f15c4b50-ee89-4927-8cf3-15e3a6a6ab95","tags":["山水","抒情","唐诗三百首","乐府","相和歌辞"]},{"id":"poem-70a67dc6103bce599d6883f9","title":"渭川田家","author":"王维","dynasty":"唐","verses":["斜阳照墟落，穷巷牛羊归。","野老念牧童，倚杖候荆扉。","雉雊麦苗秀，蚕眠桑叶稀。","田夫荷锄至，相见语依依。","即此羡闲逸，怅然吟式微。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-204e287b-8194-4c2d-808b-11cc260412ae","tags":["唐诗三百首","五言古诗","归隐","田园"]},{"id":"poem-70b9b4bcdf697f62de93da65","title":"前腔","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(贴)劝君不听，切莫再三言。","又恐官人生别见，反将恩爱变成冤。","(合前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1706","tags":[]},{"id":"poem-70c0d4d3235cf08464b7b4e4","title":"董监庙","author":"熊孺登","dynasty":"唐","verses":["仁杰淫祠废欲无，枯枫老栎两三株。","神乌惯得商人食，飞趂征帆过蠡湖。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-fc4163c1-1ab3-4d39-a2ac-1edc318d82f9","tags":[]},{"id":"poem-70c7ca4334f0f045a87d8374","title":"大云寺赞公房四首 四","author":"杜甫","dynasty":"唐","verses":["童儿汲井华，惯捷缾上手。","沾洒不濡地，埽除似无帚。","明霞烂复阁，霁雾搴高牖。","侧塞被径花，飘飖委墀柳。","艰难世事迫，隐遯佳期后。","晤语契深心，那能总箝口。","奉辞还杖策，暂别终回首。","泱泱泥污人，听听国多狗。","既未免羁绊，时来憩奔走。","近公如白雪，执热烦何有。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-2148248a-2145-43aa-86a4-dc76fd1618eb","tags":[]},{"id":"poem-70ca396cda748a07e85fd282","title":"红衫儿","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["你不信我教伊休说破，到此如何？算你爹心性，我岂不料过。","我为甚胡掩胡遮？只为着这些。","你直待要打破了砂锅，是你招灾揽祸。","(贴唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5181","tags":[]},{"id":"poem-70db1f3cb3fecb4562b5fbaa","title":"晚泊汉江渡","author":"刘畋","dynasty":"唐","verses":["末秋云木轻，莲折晚香清。","雨下侵苔色，云凉出浪声。","叠帆依岸尽，微照夹隄明。","渡吏已头白，遥知客姓名。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-b5ab00ce-47a8-423b-80f8-acccfe48dc27","tags":[]},{"id":"poem-70dc2be6197465da98c45a9f","title":"遣兴五首 二","author":"杜甫","dynasty":"唐","verses":["地用莫如马，无良复谁记。","此日千里鸣，追风可君意。","君看渥洼种，态与驽骀异。","不杂蹄啮间，逍遥有能事。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-5768d12d-f4b9-4cbe-b7ae-051ed33d6331","tags":[]},{"id":"poem-70de8643dbb123cb9cd77512","title":"奉和武相公春晓闻莺","author":"李益","dynasty":"唐","verses":["蜀道山川心易惊，缘窗残梦晓闻莺。","分明似写文君恨，万怨千愁弦上声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-663ad068-30f8-4b38-816c-eecead23bc7e","tags":[]},{"id":"poem-70e5b8ae04ab43bdb064e911","title":"荷叶杯·楚女欲归南浦","author":"温庭筠","dynasty":"唐","verses":["楚女欲归南浦，朝雨。湿愁红。","小船摇漾入花里，波起。隔西风。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-15","tags":[]},{"id":"poem-70ee9b35dd141cba28a7a977","title":"庆云见","author":"李绅","dynasty":"唐","verses":["礼成中岳陈金册，祥报卿云冠玉峰。","轻未透林疑待凤，细非行雨讵从龙。","卷风变彩霏微薄，照日笼光映隐重。","还入九霄成沆瀣，夕岚生处鹤归松。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-d30fdec9-9662-4837-8d6f-c781bf7355ae","tags":[]},{"id":"poem-70ffaa6ce679fd4abb757908","title":"赠郑十八贲","author":"杜甫","dynasty":"唐","verses":["温温士君子，令我怀抱尽。","灵芝冠众芳，安得阙亲近。","遭乱意不归，窜身迹非隐。","细人尚姑息，吾子色愈谨。","高怀见物理，识者安肯哂。","卑飞欲何待，捷径应未忍。","示我百篇文，诗家一标准。","羇离交屈宋，牢落值颜闵。","水路迷畏途，药饵驻修轸。","古人日以远，青史字不泯。","步趾咏唐虞，追随饭葵堇。","数杯资好事，异味烦县尹。","心虽在朝谒，力与愿矛盾。","抱病排金门，衰容岂为敏。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-75727b65-afda-4363-abdf-a7c94fc9e380","tags":[]},{"id":"poem-7100fee50c78d77fcd70dd9c","title":"题贾氏林泉","author":"聂夷中","dynasty":"唐","verses":["市朝束名利，林泉系清通。","岂知黄尘内，迥有白云踪。","轻流逗密𦰏，直干入宽空。","高吟五君咏，疑对九华峰。","我知种竹心，欲扇清凉风。","我知决泉意，将明济物功。","有琴不张弦，众星列梧桐。","须知澹泊听，声在无声中。","地非樵者路，武陵又何逢。","祗虑迷所归，池上日西东。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-a4ba9d47-b06b-4146-a0f7-ffbb67a35705","tags":[]},{"id":"poem-7106a980339566faa98d55bc","title":"李云南征蛮诗","author":"高适","dynasty":"唐","verses":["圣人赫斯怒，诏伐西南戎。","肃穆庙堂上，深沈节制雄。","遂令感激士，得建非常功。","料死不料敌，顾恩宁顾终。","鼓行天海外，转战蛮夷中。","梯𪩘近高鸟，穿林经毒虫。","鬼门无归客，北户多南风。","蜂虿隔万里，云雷随九攻。","长驱大浪破，急击群山空。","饷道忽已远，悬军垂欲穷。","精诚动白日，愤薄连苍穹。","野食掘田鼠，晡餐兼僰僮。","收兵列亭堠，拓地弥西东。","临事耻苟免，履危能饬躬。","将星独照耀，边色何溟蒙。","泸水夜可涉，交州今始通。","归来长安道，召见甘泉宫。","廉蔺若未死，孙吴知暗同。","相逢论意气，慷慨谢深衷。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-9d8d3ee1-81f4-4938-8797-5dcd5be1f720","tags":["战争","歌颂","将士"]},{"id":"poem-7107a58c10879116ff89d818","title":"杂诗三首 一","author":"沈佺期","dynasty":"唐","verses":["落叶惊秋妇，高砧促暝机。","蜘蛛寻月度，萤火傍人飞。","清镜红埃入，孤灯绿焰微。","怨啼能至晓，独自懒缝衣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-0e568765-f484-4616-9ca7-676b6831dc32","tags":[]},{"id":"poem-7108ff2925edd5a835cfe131","title":"蝶恋花·洒面松风凉似水","author":"张镃","dynasty":"宋","verses":["洒面松风凉似水。","下看冰泉，喷薄溪桥底。","叠叠层峰相对起。","家居却在深山里。","枝上凌霄红绕翠。","飘下红英，翠影争摇曳。","今夜岩扉休早闭。","月明定有飞仙至。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-358","tags":[]},{"id":"poem-71153a5fe73b167639cf96ec","title":"赤城李丹士","author":"王镃","dynasty":"宋","verses":["频年游岳洞，灵迹记无差。","学得长生术，常留锻死砂。","笛吹苍岛月，鞋踏赤城霞。","又欲腾空去，寻仙到九华。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-28baab79-4afb-498f-8bc4-8e91e9da86ce","tags":[]},{"id":"poem-7128e41e5d8aeb35089a3e58","title":"柳摇金","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(生)春光明媚，游人似蚁，金勒马频嘶。","万紫争妍丽，粉蝶儿成对飞。","忽听得卖花声过，忽听得卖花声过。","转过画桥西，欲卖几朵花来妆个花篮花轿儿。","(合)朝欢暮乐，效学于飞，效学于飞和你永谐连理。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8968","tags":[]},{"id":"poem-712b7fe3ac239b5c9eceb0f9","title":"哭萧渔所","author":"赵文","dynasty":"宋","verses":["于佛曾闻法，因诗遂得贫。","若为三尺喙，不了百年身。","在昔玄真子，如今主水神。","饭余茶又熟，不学泪沾巾。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-ef4ba6fe-2b12-4e6e-b84a-f7c910fbea82","tags":[]},{"id":"poem-712ef51bcc181692b39a2b46","title":"题屏","author":"刘季孙","dynasty":"宋","verses":["呢喃燕子语梁间，底事来惊梦里闲。","说与旁人浑不解，杖藜携酒看芝山。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-題屏","tags":[]},{"id":"poem-7130917aef3bc72e262cfce3","title":"伤进士谢庭皓","author":"徐夤","dynasty":"唐","verses":["献书犹未达明君，何事先游岱岳云。","惟有春风护冤魄，与生青草盖孤坟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-dfb61907-f39f-4797-8ee8-4086c79317a9","tags":[]},{"id":"poem-7135ba62fbc3875bc6ca3618","title":"送至洪沙弥赴上元受戒","author":"皎然","dynasty":"唐","verses":["不肯资章甫，胜衣被木兰。","今随秣陵信，欲及蔡州坛。","野寺钟声远，春山戒足寒。","归来次第学，应见后心难。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-54229a02-6078-4090-a29b-54f58859bbb4","tags":[]},{"id":"poem-713bf107aa08e5685a348d8a","title":"浣溪沙·红藕花香到槛频","author":"李珣","dynasty":"五代","verses":["红藕花香到槛频，可堪闲忆似花人，旧欢如梦绝音尘。","翠叠画屏山隐隐，冷铺纹簟水潾潾，断魂何处一蝉新。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-16","tags":[]},{"id":"poem-713c3d0562cb969f456e33da","title":"菩萨蛮·春花春月年年客","author":"纳兰性德","dynasty":"清","verses":["春花春月年年客，怜春又怕春离别。","只为晓风愁，催花扑玉钩。","娟娟双蛱蝶，宛转飞花侧。","花底一声歌，疼花花奈何。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-246","tags":[]},{"id":"poem-7151f22d7a65bd8401ff8b4a","title":"河传·曲槛","author":"顾敻","dynasty":"五代","verses":["曲槛，春晚。","波光渺渺，不知何处。","岸花汀草共依依，雨微，鹧鸪相逐飞。","天涯离恨江声咽，啼猿切，此意向谁说。","倚兰桡，独无聊。","魂消，小炉香欲焦。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-40","tags":[]},{"id":"poem-7169fe2c75851ad9773b16cf","title":"香柳娘","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["又重婚在洞房，重婚在洞房，将奴撇漾。","奴家一身犹可，你不思父母恩德广。","奴家指望你还有相见之日，谁想你到先亡了！痛儿夫夭亡，痛儿夫夭亡，不得耀门墙，抛弃萱花在堂上。","奴家烧此夜香呵，愿他魂归故乡，遣他魂归故乡，免得此身渺茫，早赐瑶池宴赏。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8282","tags":[]},{"id":"poem-716ad565ee772a2d87da46bc","title":"圣心","author":"张载","dynasty":"宋","verses":["圣心难用浅心求，圣学须专礼法修。","千五百年无孔子，尽因通变老优游。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-ad48f4f1-72b6-4b51-974c-802a9491f1af","tags":[]},{"id":"poem-716b7ca83e0bacbb453662ea","title":"望江怨·东风急","author":"牛峤","dynasty":"五代","verses":["东风急，惜别花时手频执。","罗帷愁独入，马嘶残雨春芜湿。","倚门立，寄语薄情郎，粉香和泪泣。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-13","tags":[]},{"id":"poem-7174b17886a5337a0deaa9c0","title":"早春雪中","author":"杨凌","dynasty":"唐","verses":["新年雨雪少晴时，屡失寻梅看柳期。","乡信忆随回鴈早，江春寒带故阴迟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-95364c77-2a32-47e0-a5f8-78f13ecdbcf1","tags":[]},{"id":"poem-7185cdb42b5a7b3b7518c4be","title":"瑞鹤仙·一枝苍玉冷","author":"高观国","dynasty":"宋","verses":["一枝苍玉冷。","爱露节霜根，从来孤劲。","提携远尘境。","自清臞骨力，岁寒心性。","登临助兴。","甚偏与，芒鞋相称。","笑葛洪、陂外腾飞，渺渺水闲烟迥。","寻胜。","拨开林影，斫破苔痕，缓支幽径。","分云度岭。","待随处、问梅信。","任香挑村醑，寒拖夜月，识尽江山好景。","扣禅关拗折，归来万缘自静。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-419","tags":[]},{"id":"poem-7187bfbd5cc940c5d4afb7b1","title":"古镜歌三首 三","author":"泰钦","dynasty":"唐","verses":["古镜精明皎皎，皎皎徧照河沙。","到处安名题字，除侬更有谁家？","过去未来现在，诸佛镜上纤瑕。","纤瑕垢尽无物，此真火里莲华。","莲花千朵万朵，朵朵端然释迦。","谁云俱尸入灭？谁云穿膝芦牙？不信镜中看取，羊车鹿车牛车。","时人不识古镜，尽道本地清净。","祇看清净是假，照得形容不正。","或圆或短或长，若有纤豪俱病。","劝君不如打破，镜去瑕消可莹。","亦见杜口毘[耶]，亦知圆通少剩。","（见景宋本《景德传灯录》卷三十。","「耶」字原缺，据《大正藏》本补）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-8b2a1e95-5dfe-4f60-aac8-26e3a2728970","tags":[]},{"id":"poem-718dc48fe76f2c0ecf90eeb2","title":"蓦山溪·挂冠神武","author":"向子𬤇","dynasty":"宋","verses":["挂冠神武。","来作烟波主。","千里好江山，都尽是、君恩赐与。","风勾月引，催上泛宅时，酒倾玉，鲙堆雪，总道神仙侣。","蓑衣箬笠，更着些儿雨。","横笛两三声，晚云中、惊鸥来去。","欲烦妙手，写入散人图，蜗角名，蝇头利，着甚来由顾。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-999","tags":[]},{"id":"poem-718f3ab7fba897d12a6e34ad","title":"上元应制","author":"蔡襄","dynasty":"宋","verses":["高列千峰宝炬森，端门方喜翠华临。","宸游不为三元夜，乐事还同万众心。","天上清光留此夕，人间和气阁春阴。","要知尽庆华封祝，四十余年惠爱深。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-上元應制","tags":[]},{"id":"poem-719295a9659e69f7aa6804ec","title":"春坊正字劒子歌","author":"李贺","dynasty":"唐","verses":["先辈匣中三尺水，曾入吴潭斩龙子。","隙月斜明刮露寒，练带平铺吹不起。","蛟胎皮老蒺藜刺，䴙鹈淬花白鹇尾。","直是荆轲一片心，莫教照见春坊字。","挼丝团金悬䍡𦌉，神光欲截蓝田玉。","提出西方白帝惊，嗷嗷鬼母秋郊哭。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-14bb787d-e384-4568-a9b7-d6dd6a447125","tags":[]},{"id":"poem-7195459264ffc06e92cab174","title":"楼上女儿曲","author":"卢仝","dynasty":"唐","verses":["谁家女儿楼上头，指挥婢子挂帘钩。","林花撩乱心之愁，卷却罗袖弹箜篌。","箜篌历乱五六弦，罗袖掩面啼向天。","相思弦断情不断，落花纷纷心欲穿。","心欲穿，凭栏干。","相忆柳条绿，相思锦帐寒。","直缘感君恩爱一回顾，使我双泪长珊珊。","我有娇靥待君笑，我有娇蛾待君扫。","莺花烂熳君不来，及至君来花已老。","心肠寸断谁得知，玉堦幂历生青草。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-6ceeebbc-4292-4d5a-ac04-4f224e649636","tags":[]},{"id":"poem-7197a577496dbfcab8343a75","title":"鹧鸪天·静乐堂中禅悦身","author":"韩淲","dynasty":"宋","verses":["静乐堂中禅悦身。","相家庆袭两家春。","瑶池云气冲霄鹤，兰砌风标瑞世麟。","华屋邃，宝杯新。","年年秋与月常明。","笙箫且奏长生曲，宣劝还看送喜频。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-424","tags":[]},{"id":"poem-7199d6f23e7100405243d097","title":"同前","author":"萧德祥《小孙屠》","dynasty":"元","verses":["燕尔新婚正欢聚，何曾肯暂离一步。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8629","tags":[]},{"id":"poem-719abda63a4b547093973d46","title":"黄钟乐·池塘烟暖草萋萋","author":"魏承班","dynasty":"五代","verses":["池塘烟暖草萋萋。","惆怅闲宵，含恨愁坐，思堪迷。","遥想玉人情事远，音容浑似隔桃溪。","偏记同欢秋月低，帘外论心，花畔和醉，暗相携。","何事春来君不见，梦魂长在锦江西。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-11","tags":[]},{"id":"poem-71a77ff8cde66ecd598894c4","title":"答僧问十二时中如何行李颂（题拟）","author":"道怤","dynasty":"唐","verses":["当此支荷得，胜于历却（疑应作「劫」）功。","多途终不是，一路妙圆通。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-cc4725f3-2a08-40ed-9e9a-f2d1e41ec064","tags":[]},{"id":"poem-71a785437279da6651eed114","title":"清平乐·离愁万斛","author":"向","dynasty":"宋","verses":["离愁万斛。","春思难拘束。","瘦尽玉肌清彻骨。","蹙损两眉秀绿。","画屏罗幌输君。","文鳞锦翼尤勤。","长记酒醒香冷，笑将髻子隈人。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-221","tags":[]},{"id":"poem-71ab55a8e25dcc7a1295a477","title":"青玉案·玉婴初有排云分","author":"毛滂","dynasty":"宋","verses":["玉婴初有排云分。","向晚色、娟娟静。","秋入风枝清不尽。","月和粉露，徘徊孤映，独夜扶疏影。","子猷风调全相称。","是彼此、无凡韵。","玉勒前头花柳近。","水边石上，冷依烟雨，时有幽人问。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-828","tags":[]},{"id":"poem-71ae7fbbd58a1353074af7b6","title":"蛮牌令犯","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(外)急急去报三公。","(旦上)见怪非怪，其怪自害。","(外)女孩儿因甚出闺门？(旦)怪哉怪哉真怪哉，见五色蛇儿坠紫青红，一步步赶来后，影也无踪。","(外)孩儿，你为何到此？(旦)奴家在绣房中做女工针指，只见天窗下调下一条花蛇。","奴家紧赶紧走，慢赶慢行，赶到这里，不见这蛇了。","(外)我儿，你可要见这蛇么？(旦)奴家要见。","在那里？(外)这不是蛇。","(旦)见着后，见着后使奴心惊，莫不是妖精把他缠定？(外)女孩儿休得气冲冲，大贵人蛇穿七窍中。","一朝运通，九霄气冲，异日轩昂把妻子来封。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8828","tags":[]},{"id":"poem-71b1f0e25f52492a7ff71c93","title":"玉楼春·轻敛翠蛾呈皓齿","author":"魏承班","dynasty":"五代","verses":["轻敛翠蛾呈皓齿，莺啭一枝花影里。","声声清迥遏行云，寂寂画梁尘暗起。","玉斝满斟情未已，促坐王孙公子醉。","春风筵上贯珠匀，艳色韶颜娇旖旎。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-3","tags":[]},{"id":"poem-71b9c3731558587b85ac05d1","title":"奉同颜使君真卿送李侍御萼赋得荻塘路","author":"皎然","dynasty":"唐","verses":["落日车遥遥，客心在归路。","细草暗回塘，春泉萦古渡。","遗踪叹芜没，远道悲去住。","寂寞荻花空，行人别无数。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-87a7ee00-8b78-4550-8957-93f9d006b994","tags":[]},{"id":"poem-71c54ff5e31ec47a869b0dfc","title":"赠孟宾于（题拟）","author":"赵晟","dynasty":"唐","verses":["上国登科建业游，鼎分踪迹便淹留。","江干旅梦三千里，海内诗名四十秋。","华表柱边人不识，烂柯山下水空流。","自从叔宝朝天后，赢得安闲养白头。","（周本淳校点本《诗话总龟》卷二八引《雅言系述》。","）（按：此诗当作于南唐授士之次年，援旧例仍收入。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-8278be13-ba08-4936-b627-56f2363b47b4","tags":[]},{"id":"poem-71cc9ac07c3faffd2cf0dcfb","title":"清明","author":"黄庭坚","dynasty":"宋","verses":["佳节清明桃李笑，野田荒冢只生愁。","雷惊天地龙蛇蛰，雨足郊原草木柔。","人乞祭余骄妾妇，士甘焚死不公侯。","贤愚千载知谁是，满眼蓬蒿共一丘。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-清明","tags":[]},{"id":"poem-71d3a907c94d2d3bf3038408","title":"来从窦车骑行","author":"李益","dynasty":"唐","verses":["束发逢世屯，怀恩抱明义。","读书良有感，学劒慙非智。","遂别鲁诸生，来从窦车骑。","追兵赴边急，络马黄金辔。","出入燕南陲，由来重意气。","自经臯兰战，又破楼烦地。","西北护三边，东南留一尉。","时过歘如云，参差不自意。","将军失恩泽，万事从此异。","置酒高台上，薄暮秋风至。","长戟与我归，归来同弃置。","自酌还自饮，非名又非利。","歌出易水寒，琴下雍门泪。","出逢平乐旧，言在天阶侍。","问我从军苦，自陈少年贵。","丈夫交四海，徒论身自致。","汉将不封侯，苏卿劳远使。","今我终此曲，此曲诚不易。","贵人难识心，何由知忌讳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-4a4e193a-a232-4a00-b6b2-65e8489a0853","tags":[]},{"id":"poem-71d41de8c46be3d69c0bc5e8","title":"句  其七","author":"杨徽之","dynasty":"宋","verses":["春归万年树，月满九重城。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-5252b7fa-bbf7-4ce9-bb2f-b4be23dc11e6","tags":[]},{"id":"poem-71d69fceb7508d99cf3a3b28","title":"乱中偷路入故乡","author":"裴说","dynasty":"唐","verses":["愁看贼火起诸烽，偷得余程怅望中。","一国半为亡国烬，数城俱作古城空。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-2d37902f-1d76-4551-9b1a-a78ea50a0400","tags":[]},{"id":"poem-71d9ab7a53553e7b2860a87c","title":"于清风楼斋坐久举目忽覩日光豁然顿晓而有偈","author":"师鼐","dynasty":"唐","verses":["清风楼上赴官斋，此日平生眼豁开。","方信普通年远事，不从葱岭带将来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-dfbf0efe-2260-42f2-9bcb-da34efd88974","tags":[]},{"id":"poem-71db6938776b9503cfd1ab6e","title":"句 一","author":"江为","dynasty":"唐","verses":["亦同元亮旧生涯。","（史铸《百菊集谱》卷六集句引。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-2772b4d3-f708-4cdf-9f02-6d7da9aad47f","tags":[]},{"id":"poem-71e9bbeea8def33afda125a2","title":"山中舒怀寄上丁学士","author":"刘得仁","dynasty":"唐","verses":["五字投精鉴，慙非大雅词。","本求闲赐览，岂料便蒙知。","幽拙欣殊幸，提携更不疑。","弱苗须雨长，懒翼在风吹。","砺镞端杨叶，光门待桂枝。","计闻尘里誉，因和禁中诗。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-d940c14b-44e3-4fa1-b3ae-7690fc7e97d9","tags":[]},{"id":"poem-71f7462da01929dd5af9e4a6","title":"渔家傲·三月清明天婉娩","author":"欧阳修","dynasty":"宋","verses":["三月清明天婉娩。","晴川祓禊归来晚。","况是踏青来处远。","犹不倦。","秋千别闭深庭院。","更值牡丹开欲遍。","酴醿压架清香散。","花底一尊谁解劝。","增眷恋。","东风回晚无情绊。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-697","tags":[]},{"id":"poem-71f92f53e3e87ec9e957ae12","title":"秋闺","author":"郑愔","dynasty":"唐","verses":["征客向轮台，幽闺寂不开。","音书秋鴈断，机杼夜蛩催。","虚幌风吹叶，闲阶露湿苔。","自怜愁思影，常共月裴回。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-b84e25ca-6a35-40f4-8ddb-65f9a52d332c","tags":[]},{"id":"poem-7200e282cc4d258fd53ddb7c","title":"客至","author":"杜甫","dynasty":"唐","verses":["舍南舍北皆春水，但见群鸥日日来。","花径不曾缘客扫，蓬门今始为君开。","盘餐市远无兼味，樽酒家贫只旧醅。","肯与邻翁相对饮，隔篱呼取尽余桮。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-9da0cbe5-52d4-4efc-8be2-2f78f1a8f097","tags":["唐诗三百首","喜悦","写景","友情","待客"]},{"id":"poem-720318521e6620c59a69d44a","title":"和史侍郎游澹岩韵六首  其四","author":"曾协","dynasty":"宋","verses":["九重温诏下江边，应览甘泉旧奏篇。","却背烟岚理归棹，晓猿夜鹤总凄然。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-1fddb3c5-795e-4d7c-b31a-da3bd2eb9af4","tags":[]},{"id":"poem-720d3c6bfde2a42a011c6da4","title":"菩萨蛮·木绵花映丛祠小","author":"孙光宪","dynasty":"五代","verses":["木绵花映丛祠小，越禽声里春光晓。","铜鼓与蛮歌，南人祈赛多。","客帆风正急，茜袖偎樯立。","极浦几回头，烟波无限愁。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-8-juan.json#record-4","tags":[]},{"id":"poem-720dc1e8febf8f5a9268fd6e","title":"感旧三首  其二","author":"王柏","dynasty":"宋","verses":["交契绸缪事未磨，月窗再得共婆娑。","君今有子全无恨，顾我伶俜奈老何。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-675fb68f-6767-4995-b9be-0b75fdbce4b0","tags":[]},{"id":"poem-72138b59e612fe31a062cdee","title":"途经华岳","author":"明皇帝","dynasty":"唐","verses":["饬驾去京邑，鸣鸾指洛川。","循途经太华，回跸暂周旋。","翠崿留斜影，悬岩冒夕烟。","四方皆石壁，五位配金天。","仿佛看高掌，依稀听子先。","终当铭岁月，从此记灵仙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-dedf14b9-362c-435a-b206-bdccc02811e3","tags":["华山"]},{"id":"poem-721afe753c73eb46c487e8c3","title":"燕山亭·玉立明光","author":"曾觌","dynasty":"宋","verses":["玉立明光，才业冠伦，汉历方承休运。","江左奏功，塞垒宣威，紫绶几垂金印。","岁晚归来，望丹极、新清氛祲。","忠愤。","著挠节朋俦，便成嘉遁。","千载云海茫茫，记举目新亭，壮怀难尽。","蝴蝶梦惊，化鹤飞还，荣华等闲一瞬。","七十尊前，算畴昔、都无可恨。","休问。","长占取、朱颜绿鬓。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-341","tags":[]},{"id":"poem-721d59bb4e78dd38a43c399d","title":"出峡","author":"胡皓","dynasty":"唐","verses":["巴东三峡尽，旷望九江开。","楚塞云中出，荆门水上来。","鱼龙潜啸雨，凫雁动成雷。","南国秋风晚，客思几悠哉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-75d52b0f-5f08-493c-ad13-74e8ca3a2a95","tags":[]},{"id":"poem-72250e0ca581f87b4052055b","title":"送黄颇归袁","author":"姚鹄","dynasty":"唐","verses":["莫倦连期在醉乡，孔门多恋惜分行。","文章声价从来重，霄汉途程此去长。","何处听猨临万壑，几宿因月滞三湘。","𬬻峰若上应相忆，不得同过惠远房。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-abd6f483-2ffd-45c3-b25a-f1f50aef5bf9","tags":[]},{"id":"poem-722c59d7d035399ad0f8f167","title":"雨中","author":"宋伯仁","dynasty":"宋","verses":["终日翻盆雨，池亭晚更凉。","对琴思古意，酾酒惜韶光。","绿涨便鸥懒，残花笑蝶忙。","高田皆可插，好与报君王。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-d9d8012a-6316-46cd-b332-eba277922858","tags":[]},{"id":"poem-722ddcd920e4ba6f28195df8","title":"柳絮","author":"雍裕之","dynasty":"唐","verses":["无风才到地，有风还满空。","缘渠偏似雪，莫近鬓毛生。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-2a995dd6-3654-4985-8822-a54a58c0896f","tags":[]},{"id":"poem-7236a07101c3a19c84c49793","title":"华严六相义颂","author":"文益","dynasty":"唐","verses":["华严六相义，同中还有异。","异若异于同，全非诸佛意。","诸佛意总别，何曾有同异。","男子身中入定时，女子身中不留意。","不留意，绝名字，万象明明无理事。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-6b24e1e2-9f7e-4321-acde-138b824d8038","tags":[]},{"id":"poem-723701382b317f0d0a926fcd","title":"春晚闲居寄陈嵩伯","author":"贯休","dynasty":"唐","verses":["春霖闭门久，春色聚庭木。","一梦辞旧山，四邻有新哭。","菰蒲生白水，风篁擢纤玉。","为忆湖上翁，花时独冥目。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-81410c71-1b7d-4b01-a4ab-2bd3fe99e3f3","tags":[]},{"id":"poem-72439e1bf563092a3b9680b2","title":"鼓吹曲辞 上之回","author":"卢照邻","dynasty":"唐","verses":["回中道路险，萧关烽候多。","五营屯北地，万乘出西河。","单于拜玉玺，天子按雕戈。","振旅汾川曲，秋风横大歌。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-fb6b3bf9-3154-4539-99f6-12b288444219","tags":[]},{"id":"poem-724638919bb0ef543b071690","title":"浣溪沙·细雨萧萧变作秋","author":"王质","dynasty":"宋","verses":["细雨萧萧变作秋。","晚风杨柳冷飕飕。","无言有泪洒西楼。","眼共云山昏惨惨，心随烟水去悠悠。","一蓑一笠任孤舟。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-313","tags":[]},{"id":"poem-724c93bcca7731075fa26469","title":"江南杂题三十首 其二十七","author":"张祜","dynasty":"唐","verses":["卜筑寄云阳，穿池面草堂。","寻常登峻岭，丈六得奇彊。","井鲋依颓甃，隣花出败墙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-349eac6a-d40e-4177-b862-4c9701c19648","tags":[]},{"id":"poem-7253c7df5b5f645ade9db544","title":"报文成金钗","author":"张𬸦","dynasty":"唐","verses":["儿今赠君别，情知复会难。","莫言钗意小，可以挂渠冠。","（〖1〗《日本图经》卷二十二《艺文志》：「《游仙窟》一卷，唐张文成。","昌平学旧写八行本、容安书院旧写九行本、尾张真福寺旧写六行本刊本，卷首题《游仙窟》，宁州襄乐县尉张文成作，小说家言也。","宁州，注云属关内道，在去京三百里西北也。","日本人言是书作嵯峨天皇时，果尔，则唐元和间也。","陈氏矩得刊本。","」〖2〗汪辟疆《唐人小说》：「按张文成《游仙窟》一卷，唐时流传日本。","书凡数刻，中土向无传本。","河世宁曾据之骏补《全唐诗》，杨守敬始著录于，日本访书志。","治唐稗者，始稍稍称焉。","余旧藏钞本，卷首有『平等阁』及『忠州李士棻随身书卷』二印记。","卷尾有『壬午三月借遵义黎氏影写本重校』小字一行，乃知此本为芋仙旧藏。","芋仙与莼斋有缟纻之雅。","黎氏在日本刻《古逸丛书》，尝以初印本寄李，李累索之，不以为贪。","则此本原钞，或即出诸黎氏，未可知也。","原钞卷首题『宁州襄乐县诗张文成作』。","世因定为唐张𬸦所撰。","𬸦字文成，深州陆泽人。","两《唐书》并附见《张荐传》。","𬸦儿时梦紫文𬸚𬸦，其祖谓是儿当以文章瑞朝廷，因以为名字。","调露初，登进士第，授岐王府参军。","八举皆登甲科，大有文誉。","调长安尉，迁鸿胪丞。","凡四参选，判策为铨府之最。","员半千谓人曰：『张子之文，如青钱万选万中。","』时目为青钱学士。","然性褊躁，不持士行。","姚崇甚薄之。","开元初，御史李全交劾𬸦讪短提政，贬岭南。","旋得内徙，入为司门员外郎。","卒。","𬸦下笔敏速，言颇诙谐，大行于时，后进莫不传记。","新罗、日本东夷诸番，尤重其文。","每遣使入朝，必出重金贝以购其文。","惟浮艳少理致，论著亦率诋诮芜秽。","〖以上摘两《唐书》有本传〗《大唐新语》亦称𬸦后转洛阳尉，故有《咏燕诗》。","其末章云：『变石身犹重，衔泥力尚微。","从来赴甲第，两起一双飞。","』时人无不讽咏云云。","今𬸦书之传于今者，有《龙筋鳯髓判》及《朝野佥载》，而《游仙窟》一卷无传，其目亦不见史志及诸家著录。","然据两《唐书》即称日本、新罗争传其文，而《新语》《咏燕》与《龙筋鳯髓》之作，浮艳鄙倍，与此篇辞旨正复相同。","据此，则《游仙窟》之出于张𬸦，当非伪造也。","」「又按《游仙窟》不传于中国，至日本人推重其书，则自唐以来，迄今弗衰，故文学蒙其影响。","其流传日本之年岁可考者，据庆安五年〖清顺治九年〗刻本，前有文保三年〖元延祐六年〗文章生英房序，有『嵯峨天生书卷之中撰得《游仙窟》』之语。","日本嵯峨天皇当唐元和、长庆间，则是中唐时此书已流传日本矣。","惟日本最古之《万叶集》卷四有大伴家持《赠坂上大𬙋歌》十五首，辞意多与此书相同，后人评论，如契冲阿阇梨，遂继为出于《游仙窟》。","前乎此者，尚在山上忆良《沈疴自哀文》亦引《游仙窟》云：『九泉下人，一钱不值。","』山上在圣武天皇天平之世，此文为山上末年之作，正当唐开元二十一年。","是此书于刊载元张𬸦尚在之时，即已传至日本，又早于嵯峨天皇八十余年。","此征诸《万叶集》可信者也。","窃意张氏此书，当为早年一时兴到之作。","当时有无寓意，今不可知。","惟日本当赵宋南渡之时，有西行法师传钞之《唐物语》一书，其第九章述及《游仙窟》本事，定为张文成爱慕武则天而作。","平康赖《宝物集》卷四亦：『则天皇后，高宗之后也。","遇好色者张文成，得《游仙窟》之文，所谓「可憎病鹊，夜半惊人」，即指当时之事也』云云。","日人幸田露伴著《蜗牛庵夜谈》，颇疑此为莲花六郎之传讹。","因易之、昌宗姓张，而二人之父为张行成，〖按易之、昌宗为张行成之族孙，非其父也。","易之父名希臧，见两《唐书》。","〗文成恰有《游仙窟》之文，遂牵合而有此一段传说，固不足深信者也。","至其书辞旨浅鄙，文气卑下，了无足取。","惟唐人口语，尚赖此略存。","」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-9a1d7f89-b3f8-4f6f-920e-4c22ca48f4fa","tags":[]},{"id":"poem-7261134fa7d477cb49bb5747","title":"闲吟","author":"周昙","dynasty":"唐","verses":["考摭妍媸用破心，翦裁千古献当今。","闲吟不是闲吟事，事有闲思闲要吟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-35b0faff-992f-41d0-a4a3-b00784bcfb34","tags":[]},{"id":"poem-726140cb84ba5fec6151907b","title":"壮节亭二松","author":"赵崇鉘","dynasty":"宋","verses":["壮节亭前野碧滋，髯龙飞去忽经时。","祇应黄犊苍藤路，尚有清泉白石知。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-c5e5d635-a3ff-45da-97f3-02fae19680d4","tags":[]},{"id":"poem-7261895663a079ee9d09c8fa","title":"遣怀","author":"杜牧","dynasty":"唐","verses":["落魄江南载酒行，楚腰肠断掌中轻。","十年一觉扬州梦，赢得青楼薄幸名。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-92ae04dc-89af-45d6-9e31-204a01df801d","tags":["唐诗三百首","七言绝句","抒怀"]},{"id":"poem-726aa6cd1a79d61fdb845d0a","title":"姑熟杂咏 天门山","author":"李赤","dynasty":"唐","verses":["迥出江水上，双峰自相对。","岸映松色寒，石分浪花碎。","参差远天际，缥缈晴霞外。","落日舟去遥，回首沈青霭。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-765fdf4b-1622-4468-a1d7-809dff28a441","tags":["天门山"]},{"id":"poem-726e1b828d68e016ec591da5","title":"女冠子·昨夜夜半","author":"韦庄","dynasty":"五代","verses":["昨夜夜半，枕上分明梦见：语多时，依旧桃花面，频低柳叶眉。","半羞还半喜，欲去又依依。觉来知是梦，不胜悲。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-21","tags":[]},{"id":"poem-72716356bef81ab7422dbe2c","title":"自蓟北归","author":"高适","dynasty":"唐","verses":["驱马蓟门北，北风边马哀。","苍茫远山口，豁达胡天开。","五将已深入，前军止半廻。","谁怜不得意，长劒独归来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-3e1b6607-1440-4c27-a25a-233c079b8011","tags":["写景","抒情","边塞","愤懑","壮志未酬"]},{"id":"poem-727a6338fb75d20235b5b4b1","title":"宿何书记先辈延福新居","author":"赵嘏","dynasty":"唐","verses":["松下有琴闲未收，一灯高为石丛留。","诗情似到山家夜，树色轻含御水秋。","小榼提携终永日，半斑容鬓漫生愁。","因君抚掌问时俗，紫阁堆簷不举头。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-4b40e046-40a9-4736-b39d-5edbe81a8288","tags":[]},{"id":"poem-727ceeae2d2bd60e4703035a","title":"郊庙歌辞 享太庙乐章 太和","author":"张说","dynasty":"唐","verses":["时文圣后，清庙肃邕。","致诚勤荐，在貌思恭。","玉节肆夏，金锵五钟。","绳绳云步，穆穆天容。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-06273196-6d2a-4c70-9680-257cea297824","tags":[]},{"id":"poem-728c6834c01a3abdff36b405","title":"送杜御史还广陵","author":"李嘉祐","dynasty":"唐","verses":["慙君从弱岁，顾我比诸昆。","同事元戎久，俱承国士恩。","随莺过淮水，看柳向辕门。","草色金陵岸，思心那可论。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-7001236e-1245-48ce-af89-43614dce03bd","tags":[]},{"id":"poem-7297898f5143c4dfd85e0c8c","title":"时事感怀  其一","author":"王同祖","dynasty":"宋","verses":["壮心如铁气填膺，万里中原尚虏尘。","一枕西风两行泪，封疆谁是死绥人。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-3df238b2-d8dc-49a2-bb3c-7eb1d275f4de","tags":[]},{"id":"poem-729afb19133ee1ed147500a8","title":"句","author":"嗣主璟","dynasty":"唐","verses":["灵槎思浩荡，老鹤倚崆峒。","苍苔迷古道，红叶乱朝霞。","栖凤枝梢犹輭弱，化龙形状已依稀。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-5c236f02-7a4d-41c6-ac4f-ae6f2cc9887f","tags":[]},{"id":"poem-729d4fe8c5451221a932d260","title":"三学山夜看圣灯","author":"蜀太妃徐氏","dynasty":"唐","verses":["圣灯千万炬，旋向碧空生。","细雨湿不暗，好风吹更明。","磬敲金地响，僧唱梵天声。","若说无心法，此光如有情。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-ca2145e0-816c-435b-8e7b-5bb087f6568c","tags":[]},{"id":"poem-72a09cda72426b9fc06a2445","title":"喜雪","author":"明皇帝","dynasty":"唐","verses":["日观卜先征，时巡顺物情。","风行未备礼，云密遽飘霙。","委树寒花发，萦空落絮轻。","朝如玉已会，庭似月犹明。","既覩肤先合，还欣尺有盈。","登封何以报？因此谢功成。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-20bfd036-c115-4eef-9a08-927a697c870c","tags":[]},{"id":"poem-72a31b19cd00432d4f613777","title":"临江仙·丝雨如尘云著水","author":"纳兰性德","dynasty":"清","verses":["丝雨如尘云著水，嫣香碎拾吴宫。","百花冷暖避东风。","酷怜娇易散，燕子学偎红。","人说病宜随月减，恹恹却与春同。","可能留蝶抱花丛。","不成双梦影，翻笑杏梁空。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-100","tags":[]},{"id":"poem-72a647bc0e6b7ddea1ad0fb7","title":"东平路作三首 三","author":"高适","dynasty":"唐","verses":["清旷凉夜月，裴回孤客舟。","渺然风波上，独爱前山秋。","秋至复摇落，空令行者愁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-d5249aa5-2cf7-4e8f-b031-c4796e6b246c","tags":[]},{"id":"poem-72afc89ae406e8b740b43fe2","title":"句 三","author":"孟宾于","dynasty":"唐","verses":["两京游寺曾题牓，五举逢知始看花。","（均见宋王禹偁《小畜集》卷二十《孟水部诗集序》引。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-f756b725-bef2-4ee0-aa00-1924ef1029e6","tags":[]},{"id":"poem-72b54b0381ae6ba0386867c3","title":"上归州刺史代通状二首 一","author":"怀濬","dynasty":"唐","verses":["家在闽山西复西，其中岁岁有莺啼。","如今不在莺啼处，莺在旧时啼处啼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-c591cbbd-4b6d-4284-a265-d29ffb1db9b4","tags":[]},{"id":"poem-72bbe4a84daaacceed039d2d","title":"渔歌子·九疑山","author":"李珣","dynasty":"五代","verses":["九疑山，三湘水，芦花时节秋风起。","水云间，山月里，棹月穿云游戏。","鼓清琴，倾绿蚁，扁舟自得逍遥志。","任东西，无定止，不议人间醒醉。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-x-juan.json#record-20","tags":[]},{"id":"poem-72c0316855b393eae4729e6b","title":"喜迁莺·边城寒早","author":"李纲","dynasty":"宋","verses":["边城寒早。","恣骄虏、远牧甘泉丰草。","铁马嘶风，毡裘凌雪，坐使一方云扰。","庙堂折冲无策，欲幸坤维江表。","叱群议，赖寇公力挽，亲行天讨。","缥缈。","銮辂动，霓旌龙旆，遥指澶渊道。","日照金戈，云随黄伞，径渡大河清晓。","六军万姓呼舞，箭发敌酋难保。","虏情慑，誓书来，从此年年修好。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-548","tags":[]},{"id":"poem-72c29bdabf48f9a9a17997e8","title":"南歌子·脸上金霞细","author":"温庭筠","dynasty":"唐","verses":["脸上金霞细，眉间翠钿深。","倚枕覆鸳衾，隔帘莺百啭，感君心。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-40","tags":[]},{"id":"poem-72c302e7b3ebb96c6fcc04c9","title":"松花","author":"释居简","dynasty":"宋","verses":["都将坠粉扫残枝，聊伴伊蒲簪蕨薇。","合赋老饕矜厚享，秋池更有芰荷衣。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-ccbd0a58-af38-4d8e-a51e-785e321bd0e3","tags":[]},{"id":"poem-72c590768d68c5a758533776","title":"登鄱阳寺阁","author":"贯休","dynasty":"唐","verses":["寺楼闲纵望，不觉到斜晖。","故国在何处，多年未得归。","寒江平楚外，细雨一鸿飞。","终𢽾於陵子，吴山有绿薇。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-f95e49cd-8338-42a1-ac92-e89688fe4b3a","tags":[]},{"id":"poem-72c5c22db22f959bd0727819","title":"古从军行","author":"李颀","dynasty":"唐","verses":["白日登山望烽火，黄昏饮马傍交河。","行人刁斗风沙暗，公主琵琶幽怨多。","野云万里无城郭，雨雪纷纷连大漠。","胡鴈哀鸣夜夜飞，胡儿眼泪双双落。","闻道玉门犹被遮，应将性命逐轻车。","年年战骨埋荒外，空见蒲桃入汉家。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-bea6f283-8f90-49b5-8842-1cb906816548","tags":["唐诗三百首","生活","冬天","乐府","边塞","相和歌辞"]},{"id":"poem-72c69829e16761c9c0987005","title":"春秋战国门 再吟","author":"周昙","dynasty":"唐","verses":["好龙天为降真龙，及见真龙瘁厥躬。","接下不勤徒好士，叶公何异鲁哀公。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-31319f1a-06c4-441d-a68a-de98bc663a47","tags":[]},{"id":"poem-72c7c66fec21c9126e17b5c9","title":"幺","author":"杨景贤","dynasty":"元","verses":["不刺刺却是战马拖缰敌将死，今日似困虎藏牙守洞时。","因老病不能辞，奉圣旨勉强行之，问师父求取法名儿。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-10105","tags":[]},{"id":"poem-72c8202b0ed07c3df3759eac","title":"奉和元日赐群臣栢叶应制","author":"赵彦昭","dynasty":"唐","verses":["器乏雕梁器，材非构厦材。","但将千岁叶，常奉万年杯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-fd70c013-9c45-4ea0-b326-15217c4a82d7","tags":["春节"]},{"id":"poem-72c97ed45e90682a70315261","title":"浪淘沙令·帘外雨潺潺","author":"李煜","dynasty":"五代","verses":["帘外雨潺潺，春意阑珊。","罗衾不耐五更寒。","梦里不知身是客，一晌贪欢。","独自莫凭栏，无限江山。","别时容易见时难。","流水落花春去也，天上人间。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-36","tags":[]},{"id":"poem-72c9b5db953e2e4526d0f737","title":"堋口逢友人","author":"卢殷","dynasty":"唐","verses":["艰难别离久，中外往还深。","已改当时法，空余旧日心。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-692fe24d-082f-4305-a4de-adfee955322b","tags":[]},{"id":"poem-72ce67d07a0616b10d55b793","title":"玉楼春·小园半夜东风转","author":"毛滂","dynasty":"宋","verses":["小园半夜东风转。","吹皱冰池云母面。","晓披阊阖见朝阳，知向碧阶添几线。","小烟弄柳晴先暖。","残雪禁梅香尚浅。","殷勤洗拂旧东君，多少韶华聊借看。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-770","tags":[]},{"id":"poem-72cfdcfc07910d27de2bfd0c","title":"和元晦雪压竹韵","author":"张栻","dynasty":"宋","verses":["山行景物总清奇，知费山翁几许诗。","雪急风号联骑日，月明霜净倚阑时。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-5601a972-19da-4a01-8a95-ec22e19dee2d","tags":[]},{"id":"poem-72d02b2ac205c264fa0b1c79","title":"送天师","author":"朱权","dynasty":"明","verses":["霜落芝城柳影疏，殷勤送客出鄱湖。","黄金甲锁雷霆印，红锦韬缠日月符。","天上晓行骑只鹤，人间夜宿解双凫。","匆匆归到神仙府，为问蟠桃熟也无。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-送天師","tags":[]},{"id":"poem-72d5385156b9770b7fe0db63","title":"题令宣和尚院","author":"贯休","dynasty":"唐","verses":["轩窗领岚翠，师得世情忘。","惟爱谈诸祖，曾经宿大荒。","泉声淹卧榻，云片犯𬬻香。","寄语题门者，看经在上方。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-aa4c2d7c-010e-4cf1-98b2-dd230dbfe621","tags":[]},{"id":"poem-72de218a6c10f6313d539632","title":"渔家傲·五月薰风才一信","author":"欧阳修","dynasty":"宋","verses":["五月薰风才一信。","初荷出水清香嫩。","乳燕学飞帘额峻。","谁借问。","东邻期约尝佳酝。","漏短日长人乍困。","裙腰减尽柔肌损。","一撮眉尖千叠恨。","慵整顿。","黄梅雨细多闲闷。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-711","tags":[]},{"id":"poem-72df6254d9fe1bce1d3c2f38","title":"早发灵芝望九华寄杜员外使君","author":"曹汾","dynasty":"唐","verses":["戴月早辞三秀馆，迟明初识久华峰。","嵯嵯玉劒寒铓利，褭褭青莲翠叶重。","奇状却疑人画出，岚光如为客添浓。","行春若到五溪上，此处褰帷正面逢。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-22730452-aa1a-4986-99d7-68ea1b0a5eaa","tags":[]},{"id":"poem-72e3f064d00711987f75d098","title":"金蕉叶","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［旦上］奈何奈何，信谗言母亲怪我，尺水翻成一丈波。","天那！是何人暗地里调唆？［见介。","净］孩儿，早知今日，悔不当初。","早依我说，不见如此。","你爹爹出去体问你丈夫消息，委实赘在万俟丞相府中了。","你爹爹说道：他那里重婚，我这里改嫁。","因此将你许了孙家了。","你可梳妆准备。","［旦］母亲差矣，王秀才是贤良儒士，未必辜恩负义。","玉莲是贞洁妇人，焉敢再嫁？他果然重婚相府，奴家情愿在家守节。","［净］什么守节？\"要知山下路，须问过来人。","\"我当时若守得定时，为何又嫁你老子？\"守节\"二字，只好口说，一个时辰也熬不得的。","［旦］母亲，此乃伤风化之言，不须提起。","［净］我儿，今番断不由你了，依了娘说，我与你母子相亲。","再若不从，朝一顿，暮一顿，打得你黄肿成病。","教你汤不得吃，水不得进。","嫁不嫁，今日还我个明白！。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8196","tags":[]},{"id":"poem-72e6729ab07a61e5e81073c2","title":"题北村六首  其一","author":"张载","dynasty":"宋","verses":["陆轴呕哑麦上场，讴歌声韵满村坊。","茅斋病叟安闲久，帝力民欢殆两忘。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-4368e441-7a1a-4e10-8f2b-d90d78676e44","tags":[]},{"id":"poem-72f085798b62476426389d4a","title":"江南回逢赵曜因送任十一赴交城主簿","author":"崔峒","dynasty":"唐","verses":["江上长相忆，因高北望看。","不知携老幼，何处度艰难。","屈指同人尽，伤心故里残。","遥怜驱匹马，白首到微官。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-931833f0-e0e1-4904-a4b3-2183940856c7","tags":[]},{"id":"poem-72f1d4324163fcddad1f4add","title":"冬日天井西峰张炼师所居","author":"皎然","dynasty":"唐","verses":["采薪逢野泉，渐见栖闲所。","坎坎山上声，幽幽林中语。","仙乡何代隐，乡服言亦楚。","开水净药苗，扫雪候山侣。","零叶聚败篱，幽花积寒渚。","冥冥孤鹤性，天外思轻举。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-747eba0a-0cbc-406d-9a8f-3e45c60a170a","tags":[]},{"id":"poem-72f6abc42178d11ad103414e","title":"高教授讣至","author":"释居简","dynasty":"宋","verses":["竞俗奔奔急，潜窥却步难。","退知藏用密，居得秉彜安。","有袜常番著，无弦敢废弹。","谢城空冷帐，回首一汍澜。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-aa7bd683-199a-4646-9709-3ee1b4f12bb7","tags":[]},{"id":"poem-730a4658485271f326e403bc","title":"赠钱郎中","author":"陈造","dynasty":"宋","verses":["刓方利禄媒，抱道俗不省。","诗书工发冢，孰起世儒病。","钱侯挺直节，蛮徼复兰省。","剑气夜星明，雕翮秋霜耿。","上前论世务，万乘为首肯。","平生中原虑，壮岁左符请。","不作黄阁想，拟试白羽秉。","孤忠当宁知，宏图时宰领。","群儿须圆曲，谓可力胜命。","彼此计乘除，得甓丧崇鼎。","平生信所得，一鉴照万境。","幕中辞脂韦，客右进严冷。","主簿聱牙伯，评俗怒生瘿。","令君强项翁，争事不藏颕。","但有周舍思，可无卫武警。","我亦意行者，泥古志未逞。","朝来听名理，剪烛延落景。","寸田殊易荒，有頼剔榛梗。","效奇乏良策，汲深慙短绠。","惟期佩公言，不堕颓俗穽。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-38fc4ead-961e-4e43-a7a2-4ef260e4aa5f","tags":[]},{"id":"poem-730de56260b4329d2afe0918","title":"送别","author":"杨凝","dynasty":"唐","verses":["樽酒邮亭暮，云帆驿使归。","野鸥寒不起，川雨冻难飞。","吴会家移遍，轩辕梦去稀。","姓杨皆足泪，非是强沾衣。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-d6ad68da-ff7c-4611-a38f-e49d2bace84d","tags":[]},{"id":"poem-731bf111da3ed8c994f9306e","title":"鹧鸪天·彩袖殷勤捧玉锺","author":"晏几道","dynasty":"宋","verses":["彩袖殷勤捧玉锺。","当年拼却醉颜红。","舞低杨柳楼心月，歌尽桃花扇影风。","从别后，忆相逢。","几回魂梦与君同。","今宵剩把银釭照，犹恐相逢是梦中。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-23","tags":["宋词三百首"]},{"id":"poem-731ea46655c39a0ea7709372","title":"喜迁莺·凭高寓目","author":"史浩","dynasty":"宋","verses":["凭高寓目。","爱屹起四窗，云南云北。","缥缈烟霞，萧森松竹，多少洞天岩谷。","著向十洲三岛，入海何妨登陆。","要知处，在皇家新赐，西湖一曲。","林麓。","真胜概，樊榭鹿亭，百卉生幽馥。","绿绮春浓，青蛇星烂，隔断世间尘俗。","笑呼羡门俦侣，时引宝觞醽醁。","醉和醒，但南山之寿，难忘勤祝。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-71","tags":["西湖"]},{"id":"poem-732ca36b089c36645c7a2964","title":"军次阳城烽舍北流泉","author":"李益","dynasty":"唐","verses":["何地可潸然，阳城烽树边。","今朝望乡客，不饮北流泉。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-8cfd97dc-c9ce-47c0-81d1-d6fcf8af6859","tags":[]},{"id":"poem-73380a11d6fc0342d1569d16","title":"喜晴","author":"曾协","dynasty":"宋","verses":["诗翁高兴动新晴，未踏湖山句已清。","领略风光初入眼，指麾泉石欲盱衡。","屡传黼扆方图旧，应有锋车便趣行。","莫向苕溪恋行乐，葵心元向太阳倾。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-d0425c07-0459-42d7-9866-393ede4088aa","tags":[]},{"id":"poem-733a06e7d0fe21a698e9ad47","title":"写怀二首 二","author":"杜甫","dynasty":"唐","verses":["夜深坐南轩，明月照我膝。","惊风飜河汉，梁栋已出日。","群生各一宿，飞动自俦匹。","吾亦驱其儿，营营为私实。","天寒行旅稀，岁暮日月疾。","荣名忽中人，世乱如虮虱。","古者三皇前，满腹志愿毕。","胡为有结绳，陷此胶与漆。","祸首燧人氏，厉阶董孤笔。","君看灯烛张，转使飞蛾密。","放神八极外，俯仰俱萧瑟。","终契如往还，得匪合仙术。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-2e87b554-124f-4a56-b208-4bdffe0550b9","tags":[]},{"id":"poem-734dbb28321d69042b27d581","title":"高风","author":"华镇","dynasty":"宋","verses":["一传肯来忘暑月，两旬轻举薄云霄。","非关汉水鱼盈钓，不为宜城酒满瓢。","方外采真欣淡泊，人间知足得逍遥。","高风可是陶彭泽，归去田园为折腰。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-a23e46bb-4b85-47e7-abc0-b53a1c4c4de6","tags":[]},{"id":"poem-735b6baede4426967bc6c2e9","title":"寄王舍人竹楼","author":"李嘉祐","dynasty":"唐","verses":["傲吏身闲笑五侯，西江取竹起高楼。","南风不用蒲葵扇，纱帽闲眠对水鸥。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-861ef4ac-6a0f-4307-a083-e0175c488c75","tags":["写物","抒情","闲适","赞美","隐居"]},{"id":"poem-7360b7d80e1378bc9148cfe9","title":"赞成功·海棠未坼","author":"毛文锡","dynasty":"五代","verses":["海棠未坼，万点深红，香包缄结一熏熏。","似含羞态，邀勒春风。","蜂来蝶去，任绕芳丛。","昨夜微雨，飘酒庭中。","忽闻声滴井边桐，美人惊起，坐听晨钟。","快教折取，戴玉璁。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-8","tags":[]},{"id":"poem-73628aa288ed54bb54fde10d","title":"舞曲歌辞 凯乐歌辞 贺圣欢","author":"不详","dynasty":"唐","verses":["四海皇风被，千年德水清。","戎衣更不著，今日告功成。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-55c332db-d62a-45b9-83ce-1b22f3261c7a","tags":[]},{"id":"poem-73630712f7f28055764b51ee","title":"偈颂七十一首  其六七","author":"释了惠","dynasty":"宋","verses":["大机普应，妙用全彰。","井通沧海，日上扶桑。","击石火，闪电光。","进前先蹉过，退后绝承当。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-b7ee94bd-431d-4f92-ab4b-2b09dd90c1f2","tags":[]},{"id":"poem-73641d64d6eb915b16a3e259","title":"长相思","author":"无名氏《张协状元》","dynasty":"元","verses":["好因缘，恶因缘。","儿又青春正少年，那堪遇状元。","儿分悭，子分悭。","马上徘徊不接鞭，浓婚结厚冤。","(末出白)覆夫人：前无旅店，后绝茅檐，村市人家难以安泊，古庙中可以少歇。","(外)相公来未？(末)相公下马来。","(丑)帮帮八帮帮。","(叫)具报！(末)具报甚人？(丑)下官下马多时，马后乐只管八帮帮帮。","(末)好，具报你。","(丑)夫人，你看一堂神道塑得精神。","(外)也是精神。","(丑)你看小鬼到长丈二。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2698","tags":[]},{"id":"poem-736e2e5b82881731c5e96cf4","title":"上林春慢·帽落宫花","author":"晁冲之","dynasty":"宋","verses":["帽落宫花，衣惹御香，凤辇晚来初过。","鹤降诏飞，龙擎烛戏，端门万枝灯火。","满城车马，对明月、有谁闲坐。","任狂游，更许傍禁街，不局金锁。","玉楼人、暗中掷果。","珍帘下、笑著春衫袅娜。","素蛾绕钗，轻蝉扑鬓，垂垂柳丝梅朵。","夜阑饮散，但赢得、翠翘双亸。","醉归来，又重向、晓窗梳裹。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-671","tags":[]},{"id":"poem-736fcc343c54cb2c824fd27c","title":"夜游宫·叶下斜阳照水","author":"周邦彦","dynasty":"宋","verses":["叶下斜阳照水。","卷轻浪、沈沈千里。","桥上酸风射眸子。","立多时，看黄昏，灯火市。","古屋寒窗底。","听几片、井桐飞坠。","不恋单衾再三起。","有谁知，为萧娘，书一纸。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-232","tags":["宋词三百首"]},{"id":"poem-73760a2a2cf0d2d471446f2f","title":"山居四景 松风","author":"李纲","dynasty":"宋","verses":["岁晚苍官鬓髪青，回风披拂自悲鸣。","不容逐客多归梦，故作江湖波浪声。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-3d5fee81-8c55-44aa-b90f-eaeff7139f27","tags":[]},{"id":"poem-737f6200a61439671c540225","title":"诗品二十四则 形容","author":"司空图","dynasty":"唐","verses":["绝伫灵素，少回清真。","如觅水影，如写阳春。","风云变态，花草精神。","海之波澜，山之嶙峋。","俱似大道，妙契同尘。","离形得似，庶几斯人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-2f623830-7ea6-45f5-9a9c-35724dd4c1ef","tags":[]},{"id":"poem-738007ffe15de3bb7698018b","title":"泛水曲","author":"王建","dynasty":"唐","verses":["载酒入烟浦，方舟泛绿波。","子酌我复饮，子饮我还歌。","莲深微路通，峰曲幽气多。","阅芳无留瞬，弄桂不停柯。","水上秋日鲜，西山碧峩峩。","兹欢良可贵，谁复更来过。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-1876a213-663e-4780-ae52-068af79122c3","tags":[]},{"id":"poem-7396d1a8e1eff546b69f1619","title":"送陈先生之洪并寄萧少卿","author":"徐铉","dynasty":"宋","verses":["闻君仙袂指洪涯，我忆情人别路赊。","知有欢娱游楚泽，更无书札到京华。","云间驿阁连江静，春满西山倚汉斜。","此处相逢应见问，为言搔首望龙沙。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-ad8b4c5c-dc85-4c6a-aab0-791d025afbdb","tags":[]},{"id":"poem-739a69c69850d328d99bc24d","title":"寄人二首  其一","author":"张佖","dynasty":"唐","verses":["别梦依依到谢家，小廊回合曲阑斜。","多情只有春庭月，犹为离人照落花。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-4ddb6dda-68be-4bb2-8874-8508c6c6e3ad","tags":["思念","唐诗三百首","七言绝句","月亮","爱情"]},{"id":"poem-739b8f104bb2ae50e34646e3","title":"玉楼春·东风本是开花信","author":"欧阳修","dynasty":"宋","verses":["东风本是开花信。","及至花时风更紧。","吹开吹谢苦匆匆，春意到头无处问。","把酒临风千万恨。","欲扫残红犹未忍。","夜来风雨转离披，满眼凄凉愁不尽。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-692","tags":[]},{"id":"poem-73a8be8159f647b01e800838","title":"绿衣","author":"佚名","dynasty":"先秦","verses":["绿兮衣兮，绿衣黄裹。心之忧矣，曷维其已！","绿兮衣兮，绿衣黄裳。心之忧矣，曷维其亡！","绿兮丝兮，女所治兮。我思古人，俾无訧兮！","𫄨兮绤兮，凄其以风。我思古人，实获我心！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-26","tags":[]},{"id":"poem-73aec99d655c0ddceec098ee","title":"韦员外东斋看花","author":"李端","dynasty":"唐","verses":["入花凡几步，此树独相留。","发艳红枝合，垂烟绿水幽。","倂开偏觉好，未落已成愁。","一到芳菲下，空招两鬓秋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-2e235fe0-7c45-444b-b33d-a317f79b6ec5","tags":[]},{"id":"poem-73b1e3c954a7b0cf670ddb5d","title":"南乡子·画舸停桡","author":"欧阳炯","dynasty":"五代","verses":["画舸停桡，槿花篱外竹横桥。","水上游人沙上女，回顾，笑指芭蕉林里住。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-1","tags":[]},{"id":"poem-73b28f8b4031e7aa6718a4e8","title":"洋州三十景 此君庵","author":"鲜于侁","dynasty":"宋","verses":["结庵已忘情，植竹更端操。","迢遥月上床，习静谁能造。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-d5a2e050-7553-4bfc-b02c-e33d15d398fe","tags":[]},{"id":"poem-73b59474ab86a09b0301b8db","title":"酬前驾部员外郎苗发","author":"李端","dynasty":"唐","verses":["马融方直校，阅简复持铅。","素业高风继，青春壮思全。","论文多在夜，宿寺不虚年。","自署区中职，同荒郭外田。","山邻三径绝，野意八行传。","煮玉矜新法，留符识旧仙。","涵苔溪溜浅，摇浪竹桥悬。","复洞潜栖燕，疎杨半翳蝉。","咏歌虽有和，云锦独成妍。","应以冯唐老，相讥示此篇。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-1912131c-ca0a-497b-86b8-c4ce48a644a0","tags":[]},{"id":"poem-73cc8fbf73c90b6955532e56","title":"偈颂七十一首  其六五","author":"释了惠","dynasty":"宋","verses":["重阳佳节到来，瑞岩无可安排。","一十二峰黄栗粽，东大洋海茱萸茶。","万象摩唇捋嘴，虚空缀齿粘牙，不知秋意落谁家。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-420ab5be-12a0-4e97-aefb-7138ee8490a9","tags":[]},{"id":"poem-73d38182b7d02741d0f82009","title":"小明","author":"佚名","dynasty":"先秦","verses":["明明上天，照临下土。我征徂西，至于艽野。二月初吉，载离寒暑。","心之忧矣，其毒大苦。念彼共人，涕零如雨。岂不怀归？畏此罪罟！","昔我往矣，日月方除。曷云其还？岁聿云莫。念我独兮，我事孔庶。","心之忧矣，惮我不暇。念彼共人，眷眷怀顾！岂不怀归？畏此谴怒。","昔我往矣，日月方奥。曷云其还？政事愈蹙。岁聿云莫，采萧获菽。","心之忧矣，自诒伊戚。念彼共人，兴言出宿。岂不怀归？畏此反复。","嗟尔君子，无恒安处。靖共尔位，正直是与。神之听之，式谷以女。","嗟尔君子，无恒安息。靖共尔位，好是正直。神之听之，介尔景福。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-206","tags":[]},{"id":"poem-73d5129163f3369e4166c98c","title":"临江仙·十二高峰天外寒","author":"阎选","dynasty":"五代","verses":["十二高峰天外寒，竹梢轻拂仙坛。","宝衣行雨在云端，画帘深殿，香雾冷风残。","欲问楚王何处去？翠屏犹掩金鸾。","猿啼明月照空滩，孤舟行客，惊梦亦艰难。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-22","tags":[]},{"id":"poem-73e13468bbe0fc4455107819","title":"偈","author":"契从","dynasty":"唐","verses":["烈士锋前少人陪，云雷击鼓剑轮开。","谁是大雄师子种，满身锋刃但出来。","（《景德传灯录》卷二四、《五灯会元》卷八。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-a0461a52-91a9-4916-9608-b441ada35438","tags":[]},{"id":"poem-73e2aa69130218813d419f27","title":"游洞庭湖","author":"裴说","dynasty":"唐","verses":["楚云团翠八百里，澧兰吹香堕春水。","白头渔子摇苍烟，㶉𫛶眠沙晓惊起。","沙头龙叟夜叹忧，铁笛未响春风羞。","露寒紫藟结新愁，城角泣断关河秋。","谪仙欲识雷斧手，刬却古今愁共丑。","鲸游碧落杳无踪，作诗三叹君知否。","瀛洲一櫂何时还，满江宫锦看湖山。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-38690232-17dc-4a98-99d6-07f8c59e37e3","tags":["洞庭湖"]},{"id":"poem-73ed9c8abd6ba592e70b439c","title":"鹦鹉","author":"子兰","dynasty":"唐","verses":["翠毛丹觜乍教时，终日无寥似忆归。","近来偷解人言语，乱向金笼说是非。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-4a11a829-508c-41c4-8486-820e78ea4b7a","tags":[]},{"id":"poem-740425042e9936dbf1d187de","title":"百丈潭","author":"陈岩","dynasty":"宋","verses":["目观溶溶眩水精，耳根虩虩受雷声。","一杯更吸潭间味，并要胸中领此清。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-5d6166c9-1b94-4fa1-a995-70bc90dc6817","tags":[]},{"id":"poem-7409b8d4113d277fccb05321","title":"菩萨蛮·赤阑桥尽香街直","author":"陈克","dynasty":"宋","verses":["赤阑桥尽香街直。","笼街细柳娇无力。","金碧上青空。","花晴帘影红。","黄衫飞白马。","日日青楼下。","醉眼不逢人。","午香吹暗尘。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-270","tags":["宋词三百首"]},{"id":"poem-74159e8f3159c8038d7dd9be","title":"江城子·画楼帘幕卷新晴","author":"卢祖皋","dynasty":"宋","verses":["画楼帘幕卷新晴。","掩银屏。","晓寒轻。","坠粉飘香，日日唤愁生。","暗数十年湖上路，能几度，著娉婷。","年华空自感飘零。","拥春酲。","对谁醒。","天阔云闲，无处觅箫声。","载酒买花年少事，浑不似，旧心情。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-188","tags":["宋词三百首"]},{"id":"poem-7415a7fa24a27cabbd3bbe2c","title":"前腔","author":"施惠《幽闺记》","dynasty":"元","verses":["(丑)潋滟流霞。","(生)酒保，你怎么把脸儿遮了？(丑)小人脸儿不那个，恐娘子见了不肯吃酒。","不比寻常卖酒家。","娘子请一杯。","(旦)我不会吃。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2978","tags":[]},{"id":"poem-7417d03bf80e37d66c25166c","title":"叙事献同州侍御三首 二","author":"赵嘏","dynasty":"唐","verses":["平生望断云层层，紫府杳是他人登。","却应归访溪边寺，说向当时同社僧。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-c3b2b5f8-01d0-4af1-ac31-d5263defb7c9","tags":[]},{"id":"poem-741dda421ac4e30f1e542d26","title":"宗夫人挽章","author":"王柏","dynasty":"宋","verses":["勋烈高忠简，夫人衍庆源。","春风南涧藻，秋雨北堂萱。","鸾鉴伤孤影，芝庭茂两孙。","清霜凝素仗，璀璨满西原。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-abba583c-376e-4236-a7ee-bb310c2328a0","tags":[]},{"id":"poem-7422ef5e6257e2f1495dcaed","title":"渔家傲·雪月照梅溪畔路","author":"薛几圣","dynasty":"宋","verses":["雪月照梅溪畔路。","幽姿背立无言语。","冷浸瘦枝清浅处。","香暗度。","妆成处士横斜句。","浑似玉人常淡伫。","菱花相对成清楚。","谁解小图先画取。","天欲曙。","恐随月色云间去。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-894","tags":[]},{"id":"poem-74275bc899f19523bd8504a3","title":"应天长·绿槐阴里黄莺语","author":"韦庄","dynasty":"五代","verses":["绿槐阴里黄莺语，深院无人春昼午。","画帘垂，金凤舞，寂寞绣屏香一炷。","碧天云，无定处，空有梦魂来去。","夜夜绿窗风雨，断肠君信否。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-41","tags":[]},{"id":"poem-742b07a82f5a3c76858af964","title":"奉和李右相赏会昌林亭","author":"孙逖","dynasty":"唐","verses":["贤相初陪跸，灵山本降神。","作京雄近县，开阁宠平津。","地胜林亭好，时清宴赏频。","百泉萦草木，万井布郊畛。","德与春和盛，功将造化邻。","还嗤渭滨叟，岁晚独垂纶。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-d6c82554-53e1-411c-9211-20bdc5147204","tags":[]},{"id":"poem-742b29814c18c0881ce2a9e1","title":"归国遥·春欲晚","author":"韦庄","dynasty":"五代","verses":["春欲晚，戏蝶游蜂花烂漫。","日落谢家池馆，柳丝金缕断。","睡觉绿鬟风乱，画屏云雨散。","闲倚博山长叹，泪流沾皓腕。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-40","tags":[]},{"id":"poem-742d7ab1705fa8f40a0707c8","title":"鼓吹曲辞 朱鹭","author":"张籍","dynasty":"唐","verses":["翩翩兮朱鹭，来泛春塘栖绿树。","羽毛如翦色如染，远飞欲下双翅敛。","避人引子入深壍，动处水纹开滟滟。","谁知豪家网尔躯，不如饮啄江海隅。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-39c8eb21-2fd1-42bb-9540-3ff56ea983c3","tags":[]},{"id":"poem-742e70f3e4217010068616e6","title":"杂曲歌辞 长干曲四首 一","author":"崔颢","dynasty":"唐","verses":["君家定何处？妾住在横塘。","停舟暂借问，或恐是同乡。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-4bef9a5e-f4a1-44bd-a78c-cb0fe38ccdff","tags":["孤独","女子","思乡","唐诗三百首","乐府"]},{"id":"poem-7436d27e84dfc4a90b20e2d6","title":"已凉","author":"韩偓","dynasty":"唐","verses":["碧阑干外绣帘垂，猩血屏风画折枝。","八尺龙须方锦褥，已凉天气未寒时。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-1deac6d5-6da0-4d9f-a182-2f0697cbb932","tags":["唐诗三百首","七言绝句","爱情","写景","婉约"]},{"id":"poem-743cc6aafe185e811f6170ea","title":"题僧壁","author":"赵嘏","dynasty":"唐","verses":["晓望疎林露满巾，碧山秋寺属闲人。","溪头尽日看红叶，却笑高僧衣有尘。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-9af8d6c8-ded8-44d3-a3d9-c1f17bd23f34","tags":[]},{"id":"poem-7440b009f964d63250b19087","title":"郊庙歌辞 祀九宫贵神乐章 豫和 六","author":"不详","dynasty":"唐","verses":["崇崇泰坛，灵具临兮。","铿锽大乐，振动心兮。","神之降矣，卿云郁兮。","神之至止，清风肃兮。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-73235558-2399-4730-b8d9-d7dafb45ac29","tags":[]},{"id":"poem-745239ab75bb7613d9697bd2","title":"看花","author":"何元","dynasty":"唐","verses":["莫怪出门先骤马，暮年常怨看花迟。","可怜尽日春山下，似雪如云一万枝。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-f78c57ff-c6a6-4a18-9412-3024660d7cd0","tags":[]},{"id":"poem-74541d10b9e3cfc1fe58f81b","title":"和主司王起","author":"丘上卿","dynasty":"唐","verses":["常将公道选诸生，不是鸳鸿不得名。","天上宴回联步武，禁中麻出满寰瀛。","簪裾尽过前贤贵，门馆仍叨旧学荣。","看著凤池相继入，都堂那肯滞关营。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-f7cea501-63bf-4629-be32-2c452d3fa8e0","tags":[]},{"id":"poem-745abe692f4a33715adde6b6","title":"踏雪寻梅","author":"王镃","dynasty":"宋","verses":["探春绕遍玉阑干，香暗冰痕屐齿寒。","怕有花头遭冻损，枝枝呵手掐来看。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-66f65ae3-79e4-4e06-800e-ad23450d2627","tags":[]},{"id":"poem-745c28ff6594af74333f569c","title":"随州献李侍御二首 一","author":"姚鹄","dynasty":"唐","verses":["彩笔曾专造化权，道尊翻向宦途闲。","端居有地唯栽药，静坐无时不忆山。","德望旧悬霄汉外，政声新溢路歧间。","众知圣主搜贤相，朝夕欲徴黄霸还。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-6ea858a2-2beb-4a9f-945d-d13ae55873bc","tags":[]},{"id":"poem-746eeba1dea08b23b35a6a45","title":"数日","author":"赵崇鉘","dynasty":"宋","verses":["数日东风欺病骨，侵凌晓色作轻寒。","客来坐久无谈柄，共看游丝上井栏。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-5fb56e07-2b7b-44a0-b9da-d7456d8fe2dd","tags":[]},{"id":"poem-7487ae2e5fc229b562c92552","title":"春秋战国门 百里奚","author":"周昙","dynasty":"唐","verses":["船骥由来是股肱，在虞虞灭在秦兴。","裁量何异刀将尺，秪系用之能不能。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-67892ebe-6081-4b38-bee6-0dfcd6aacbcc","tags":[]},{"id":"poem-748a9506a1a95c40549e5688","title":"送长社胡明府","author":"徐铉","dynasty":"宋","verses":["黄绶系未稳，桂枝香尚新。","琴堂宁久次，谏署正求人。","皎皎凉秋月，飘飘清路尘。","元常有遗翰，求作箧中珍。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-40bef844-9932-4695-a19e-700be1316fc8","tags":[]},{"id":"poem-748bbedd044044102df26aca","title":"临江仙","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(小生)被打出门珠泪流，教人羞耻向谁投？哥哥因甚赶无休？在他檐下过，怎敢不低头！。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1718","tags":[]},{"id":"poem-749682e214b2a2c8382695bd","title":"声声慢·宫梅粉淡","author":"赵佶","dynasty":"宋","verses":["宫梅粉淡，岸柳金匀，皇州乍庆春回。","凤阙端门，棚山彩建蓬莱。","沈沈洞天向晚，宝舆还、花满钧台。","轻烟里，算谁将金莲，陆地齐开。","触处声歌鼎沸，香鞯趁，雕轮隐隐轻雷。","万家帘幕，千步锦绣相挨。","银蟾皓月如昼，共乘欢、争忍归来。","疏钟断，听行歌、犹在禁街。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-526","tags":[]},{"id":"poem-749a5091d7b455c8aea4d5a6","title":"送郭良辅下第东归","author":"李端","dynasty":"唐","verses":["献策不得意，驰车东出秦。","暮年千里客，落日万家春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-999dbf81-f5a8-4f71-87b3-54bd70dbeab0","tags":[]},{"id":"poem-74a3309d97ea0078d8d82466","title":"使辽作十四首  其一三","author":"刘跂","dynasty":"宋","verses":["王春今日是，虏历自相忘。","厌食干羊味，如闻生菜香。","陇梅浑破腊，燕雁正随阳。","时节催归兴，凭陵天际翔。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-3029bb91-2092-4d62-a646-88bd81f4ebea","tags":[]},{"id":"poem-74af5356b3f8b9e8602c41eb","title":"九歌·东皇太一","author":"屈原","dynasty":"先秦","verses":["吉日兮辰良，穆将愉兮上皇。","抚长剑兮玉珥，璆锵鸣兮琳琅。","瑶席兮玉瑱，盍将把兮琼芳。","蕙肴蒸兮兰藉，奠桂酒兮椒浆。","扬枹兮拊鼓，疏缓节兮安歌。","陈竽瑟兮浩倡。","灵偃蹇兮姣服，芳菲菲兮满堂。","五音纷兮繁会，君欣欣兮乐康。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-1","tags":[]},{"id":"poem-74b77ed0f470373531c0c2b2","title":"雨霖铃·天南游客","author":"黄裳","dynasty":"宋","verses":["天南游客。","甚而今、却送君南国。","薰风万里无限，吟蝉暗续，离情如织。","秣马脂车，去即去、多少人惜。","为惠爱、烟惨云山，送两城愁作行色。","飞帆过、浙西封域。","到秋深、且舣菏花泽。","就船买得鲈鳜。","新谷破、雪堆香粒。","此兴谁同，须记东秦，有客相忆。","愿听了、一阕歌声，醉倒拚今日。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-615","tags":[]},{"id":"poem-74c22bfb5482a190af8a36f6","title":"和秉国芙蓉五章  其二","author":"司马光","dynasty":"宋","verses":["北方稀见诚奇物，笔界轻丝指捻红。","楚蜀可怜人不赏，墙根屋角数无穷。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-971d901c-d58c-425f-824a-f45112bc9946","tags":[]},{"id":"poem-74d643dba09cc81fbe37f263","title":"追次东坡和郁林王守韵","author":"李纲","dynasty":"宋","verses":["盖世文章妙语言，谁令骨相似虞翻。","玉堂大手空遗迹，海岛幽栖有断垣。","仙去公宁怀此土，生还我亦荷寛恩。","龙虬满纸疑飞动，尚想挥毫气象轩。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-2be3376e-724f-4cb3-b091-1501a9ba4825","tags":[]},{"id":"poem-74d6dfa5e2ad84334905aff9","title":"荷叶杯·金鸭香浓鸳被","author":"顾敻","dynasty":"五代","verses":["金鸭香浓鸳被，枕腻。","小髻簇花钿，腰如细柳脸如莲。","怜么怜，怜么怜。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-27","tags":[]},{"id":"poem-74d9e073586db4247634dd30","title":"瞻卬","author":"佚名","dynasty":"先秦","verses":["瞻卬昊天，则不我惠。孔填不宁，降此大厉。邦靡有定，士民其瘵。","蟊贼蟊疾，靡有夷届。罪罟不收，靡有夷瘳。","人有土田，女反有之。人有民人，女覆夺之。此宜无罪，女反收之。","彼宜有罪，女覆说之。","哲夫成城，哲妇倾城。懿厥哲妇，为枭为鸱。妇有长舌，维厉之阶。","乱匪降自天，生自妇人。匪教匪诲，时维妇寺。","鞫人忮忒。谮始竞背。岂曰不极？伊胡为慝？如贾三倍，君子是识。","妇无公事，休其蚕织。","天何以剌？何神不富？舍尔介狄，维予胥忌。不吊不祥，威仪不类。","人之云亡，邦国殄瘁。","天之降罔，维其优矣。人之云亡，心之忧矣。天之降罔，维其几矣。","人之云亡，心之悲矣。","觱沸槛泉，维其深矣。心之忧矣，宁自今矣？不自我先，不自我后。","藐藐昊天，无不克巩。无忝皇祖，式救尔后。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-263","tags":[]},{"id":"poem-74db907cdc20d44ca7777d9a","title":"忆王孙·凉生冰簟怯衣单","author":"蔡伸","dynasty":"宋","verses":["凉生冰簟怯衣单。","明月楼高空画栏。","满院啼螀人未眠。","掩重关。","乌鹊南飞风露寒。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-994","tags":[]},{"id":"poem-74dd3e27c835647fce09d799","title":"颂古七十六首  其六","author":"释士珪","dynasty":"宋","verses":["种谷不生豆苗，蒸沙岂能成饭。","大通智胜如来，一个担扳底汉。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-059d4216-829c-41c2-a0a6-7df5d9336c5f","tags":[]},{"id":"poem-74e0f2983477d407cc54404b","title":"郊庙歌辞 雩祀乐章 舒和","author":"褚亮","dynasty":"唐","verses":["凤曲登歌调令序，龙雩集舞泛祥风。","彩旞云回昭睿德，朱干电发表神功。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-26bff9a0-801b-4f40-b3ef-2567d01373b0","tags":[]},{"id":"poem-74e15c8f1f9d2a05c5c9f609","title":"累字戏作解愁吟简旧同寮","author":"宋伯仁","dynasty":"宋","verses":["愁。","知不。","空白头。","心事惊秋。","归兴满沧洲。","貂蝉虽出兜鍪。","功名有愧黑貂裘。","夷齐与盗跖总荒丘。","无非蘧蘧栩栩梦庄周。","空教笑倒江上烟雨汀鸥。","一琴一剑一童一鹤一茶瓯。","自不须苦苦高卧元龙百尺楼。","著眼看翻云覆雨处豪杰总成羞。","牙旗金甲蹇馿破帽穷通一任前修。","五湖千万顷明月则尽可棹歌横钓舟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-ff4c9a83-36a9-4e50-aa78-8b02b81d79b3","tags":[]},{"id":"poem-74e66246b224990fd67da8ee","title":"河南府试十二月乐词 六月","author":"李贺","dynasty":"唐","verses":["裁生罗，伐湘竹。","帔拂疎霜簟秋玉，炎炎红镜东方开。","晕如车轮上裴回，啾啾赤帝骑龙来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-94a3e3ca-a454-4c8d-a7ac-db2972824153","tags":[]},{"id":"poem-74ea812007c2e8f621a7aec9","title":"送高遂赴举","author":"祝元膺","dynasty":"唐","verses":["句曲旧宅真，自产日月英。","既涵岳渎气，安无神仙名。","松桂逦迤色，与君相送情。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-480467a5-65ca-4ff9-8a00-c3d2a2727f91","tags":[]},{"id":"poem-74f4b0cebd4b50fb3e833748","title":"寄张霖溪","author":"蒋芸","dynasty":"宋","verses":["漫向潭源晦此身，自嗟无地可投明。","栽培劲节依岩翠，采撷香芹遶涧清。","避乱遣怀聊圃治，论交且喜傍山行。","何时并辔临溪上，静听飞泉万壑声。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-1496039a-2c9f-41b2-974a-19924167614f","tags":[]},{"id":"poem-74f6b7d2d7f7503a871027ff","title":"富贵曲二首 二","author":"贯休","dynasty":"唐","verses":["如神若仙，似兰同雪。","乐戒于极，胡不知辍。","只欲更缀上落花，恨不能把住明月。","太山肉尽，东海酒竭。","佳人醉唱，敲玉钗折。","宁知耘田车水翁，日日日灸背欲裂。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-94a77918-76c6-44f6-8e8e-58fb7dd978d5","tags":[]},{"id":"poem-74fc8f71a484169360648070","title":"和元晦马迹桥","author":"张栻","dynasty":"宋","verses":["便请行从马迹桥，何须乘鹤簉丛霄。","殷勤底事登临去，不为山僧苦见招。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-faa9e79d-4d8f-4a0c-ae41-e7d6aa66b6cb","tags":[]},{"id":"poem-74fe99fae33062e40d822320","title":"夜宿赤松梅师房","author":"王柏","dynasty":"宋","verses":["梅师有松度，萧散意态真。","皮冠簪白雪，布褐贮阳春。","房计任简淡，了无一虑尘。","茶一碗，酒一尊，熙熙天地一闲人。","名山浮爽秀，朝暮瀹尔神。","餐霞炼日气，井灶求遗珍。","希夷仙境本不远，何用抱朴终其身。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-8c58ffb5-2957-4d77-9c4b-c3e858a71737","tags":[]},{"id":"poem-750708dfdac8f0dd2fc2536b","title":"忆周秀才素上人时闻各在一方","author":"孟郊","dynasty":"唐","verses":["东西分我情，魂梦安能定。","野客云作心，高僧月为性。","浮云自高闲，明月常空净。","衣敝得古风，居山无俗病。","吟听碧云语，手把青松柄。","羡尔欲寄书，飞禽杳难倩。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-e7b782c4-dbcf-497a-b9ef-63ceacc60522","tags":[]},{"id":"poem-751d0f8e586fb1ae696c80f8","title":"渔人","author":"宋伯仁","dynasty":"宋","verses":["不求豪富不求官，衣钵相传一钓竿。","醉展绿蓑眠便得，满城风雨自春寒。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-b77ee346-78c2-427b-aa10-aadfd2a717ca","tags":[]},{"id":"poem-75231c140ca09c2e2e72d7eb","title":"送王监丞之历阳","author":"徐铉","dynasty":"宋","verses":["叹息曾游处，江边故郡城。","青襟空皓首，往事似前生。","绿绶君重绾，华簪我尚荣。","年衰俱近道，莫话别离情。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-e224b06d-52c6-4689-8f2c-f0cddb9551ea","tags":[]},{"id":"poem-7526c4ae67db0352c76d7f3f","title":"和景仁七十一偶成","author":"司马光","dynasty":"宋","verses":["心地长闲为己物，年华不住是天时。","当时海上乘槎客，维楫都无任所之。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-d9bb486e-55b3-4195-9513-21604fdaac19","tags":[]},{"id":"poem-75277e4e7176a8b9b64dd946","title":"更漏子·星渐稀","author":"牛峤","dynasty":"五代","verses":["星渐稀，漏频转，何处轮台声怨。","香阁掩，杏花红，月明杨柳风。","挑锦字，记情事，惟愿两心相似。","收泪语，背灯眠，玉钗横枕边。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-10","tags":[]},{"id":"poem-752789781188220ac60fdfba","title":"落花时·夕阳谁唤下楼梯","author":"纳兰性德","dynasty":"清","verses":["夕阳谁唤下楼梯，一握香荑。","回头忍笑阶前立，总无语，也依依。","笺书直恁无凭据，休说相思。","劝伊好向红窗醉，须莫及，落花时。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-74","tags":[]},{"id":"poem-7527e516c51ccb8c71db8016","title":"淳熙四年二月既望静江守臣张某奉诏劝农于郊乃作熙熙阳春之诗二十四章章四句以示父老俾告于其乡之人而歌之  其一一","author":"张栻","dynasty":"宋","verses":["不念其本，则越其思。","所思既越，害斯百罹。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-75c6170b-fa8c-445a-b0bf-f0c9e1cde11a","tags":[]},{"id":"poem-7531c004acbdba5b61089bad","title":"菩萨蛮·红楼别夜堪惆怅","author":"韦庄","dynasty":"五代","verses":["红楼别夜堪惆怅，香灯半卷流苏帐。","残月出门时，美人和泪辞。","琵琶金翠羽，弦上黄莺语。","劝我早归家，绿窗人似花。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-33","tags":[]},{"id":"poem-7538c6c8fca1118598e569bb","title":"题金华宫","author":"蜀太妃徐氏","dynasty":"唐","verses":["碧烟红雾漾人衣，宿雾苍苔石径危。","风巧解吹松上曲，蝶娇频采脸边脂。","同寻僻境思携手，暗指遥山学画眉。","好把身心清净处，角冠霞帔事希夷。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-7c225364-4e21-428e-ac41-013a9eb0d8bb","tags":[]},{"id":"poem-753c6119e47b3792c0a9296a","title":"渔阳","author":"杜甫","dynasty":"唐","verses":["渔阳突骑犹精锐，赫赫雍王都节制。","猛将飘然恐后时，本朝不入非高计。","禄山北筑雄武城，旧防败走归其营。","系书请问燕耆旧，今日何须十万兵。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-d00e139f-4480-4c4a-afbf-5cdc94ad8714","tags":[]},{"id":"poem-753cd0322c2c169e96fedecc","title":"郡城南曰琼台北曰语海余易之曰云海登眺有感  其一","author":"李纲","dynasty":"宋","verses":["孤城南面敞琼台，千里川原指顾开。","试向绿云深处望，海山浮动见蓬莱。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-1603d8f8-2903-4fdf-be04-acab71d6be63","tags":[]},{"id":"poem-7543d92ea5e6a719e89766d3","title":"酬姜贫乐","author":"释居简","dynasty":"宋","verses":["我欲渊明伯仲间，为谁干没静中闲。","直将目送孤鸿度，横截湖飞短艇还。","稍闲便同搜万象，更忙亦可看孤山。","是闲真隠多余地，玄豹何尝肯露斑。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-52ea5e88-546a-46e0-afee-74399cd54c27","tags":[]},{"id":"poem-7545c63f7e54e610a4f8768e","title":"读史","author":"鲍溶","dynasty":"唐","verses":["鬼书报秦亡，天地亦云闭。","赤龙吟大野，老[母]哭白帝。","苍苍无白日，项氏徒先济。","六合已姓刘，鸿门事难制。","坑降嬴政在，衣锦人望替。","宿昔见汉兵，龙蛇满旌棨。","始矜山可拔，终叹骓不逝。","区区亚父心，未究天人际。","萧张马无汗，盛业垂千世。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-0da128ae-3425-4b49-9dd3-1c1cd99e9030","tags":[]},{"id":"poem-75577289f51a1f0d759e6d3f","title":"褰裳","author":"佚名","dynasty":"先秦","verses":["子惠思我，褰裳涉溱。子不我思，岂无他人？狂童之狂也且！","子惠思我，褰裳涉洧。子不我思，岂无他士？狂童之狂也且！"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-86","tags":[]},{"id":"poem-7559bb128526973c4f8efdf2","title":"江行无题一百首 三十四","author":"钱珝","dynasty":"唐","verses":["睡稳叶舟轻，风微浪不惊。","人居芦苇岸，终夜动秋声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-cb8e0968-f859-4970-9642-31ea524a118d","tags":[]},{"id":"poem-755ae8d0b79ae3dfe3ee03b1","title":"湖上","author":"宋伯仁","dynasty":"宋","verses":["一泓寒玉浸青山，粧点楼台夕照间。","歌管满船春未嬾，惜无人伴白鸥闲。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-8f678cb3-3e35-4a0a-a34a-ab945f003457","tags":[]},{"id":"poem-755bb65df7171f79c1371d59","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["［净上］白面儿郎，学疏才不广。","粗豪狂放，指银瓶，索酒尝。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8022","tags":[]},{"id":"poem-7563eca5104b8fd2a50db138","title":"正日临朝","author":"太宗皇帝","dynasty":"唐","verses":["条风开献节，灰律动初阳。","百蛮奉遐賮，万国朝未央。","虽无舜禹迹，幸欣天地康。","车轨同八表，书文混四方。","赫奕俨冠盖，纷纶盛服章。","羽旄飞驰道，钟鼓震岩廊。","组练辉霞色，霜戟耀朝光。","晨宵怀至理，终媿抚遐荒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-bb81eac8-221c-4d0a-89d7-aa4c0f01d8a1","tags":[]},{"id":"poem-756836e409f9418d4ad7bbf1","title":"吊进士杨邺","author":"卢肇","dynasty":"唐","verses":["名未荣身亲在堂，九重泉路去何忙。","夫妻镜里鸾分影，兄弟云中雁断行。","林木萧疏花失色，池亭牢落月无光。","思君欲向灵山哭，又恐猿闻更断肠。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-cc0d859d-e13c-4ea7-88e8-b7735d131dc9","tags":[]},{"id":"poem-756c95f0be7da1b36aa9a577","title":"宝峰亭","author":"鲜于侁","dynasty":"宋","verses":["舟航日上下，车马不少闲。","近邑凑商贾，远峰自云烟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-a3ba4eca-69db-4935-80e8-603747077c11","tags":[]},{"id":"poem-756d95fab466bc2a75213ef9","title":"上元怀古二首 一","author":"李山甫","dynasty":"唐","verses":["南朝天子爱风流，尽守江山不到头。","总是战争收拾得，却因歌舞破除休。","尧行道德终无敌，秦把金汤可自由。","试问繁华何处有，雨苔烟草古城秋。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-847539b6-7ea7-4aec-a7ff-7a32da3e8c6b","tags":[]},{"id":"poem-756fd773bc630387325b1d71","title":"山居","author":"李咸用","dynasty":"唐","verses":["草堂书一架，苔径竹千竿。","难世投谁是，清贫且自安。","邻居皆学稼，客至亦无官。","焦尾何人听，凉宵对月弹。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-efbe7067-6be0-4f7e-8a3f-5e9d225940e0","tags":[]},{"id":"poem-7577263238f4dce448d7034a","title":"初发雷阳有感二首  其二","author":"李纲","dynasty":"宋","verses":["余生幸尔脱垂涎，鸡肋安能拒老拳。","万里得归辞瘴海，三年奔命厌征轩。","采薇散髪嵇中散，开灶烧丹葛稚川。","此去山林如脱兔，这回且结好因缘。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-0e17705d-021a-4b40-beb2-1b26a484d767","tags":[]},{"id":"poem-757b801a3f354f7664ffe42b","title":"渔歌子·晓风清","author":"顾敻","dynasty":"五代","verses":["晓风清，幽沼绿，倚栏凝望珍禽浴。","画帘垂，翠屏曲，满袖荷香馥郁。","好摅怀，堪寓目，身闲心静平生足。","酒杯深，光影促，名利无心较逐。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-7-juan.json#record-30","tags":[]},{"id":"poem-7589932be02639532855a50d","title":"五样锦","author":"施惠《幽闺记》","dynasty":"元","verses":["姻缘将谓五百年眷属。","十生九死成欢聚。","经艰历险，幸然无虞。","也指望否极生泰，祸绝受福。","未妥，尚有如是苦：急浪狂风，风吹折并根连枝树；浪惊散鸳鸯两处孤，更全然不想我这病体疾躯。","那肯放容他些儿个叮咛嘱付，将他倒拽横拖奔去途。","回头道不得声将息，几曾有这般慈父！跌得我气绝再复。","死绝再苏，一回价上心来，一回价痛哭。","暮雨朝云去不还，强移栖息一枝安；春蚕到老丝方尽，蜡烛成灰泪始干。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-3039","tags":[]},{"id":"poem-758bfbd4f423f65eee7514a6","title":"留别南溪二首 二","author":"李渤","dynasty":"唐","verses":["如云不厌苍梧远，似鴈逢春又北归。","惟有隐山溪上月，年年相望两依依。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-10719e77-ef12-475d-9f69-be8809c12649","tags":[]},{"id":"poem-75932ad1ef53d537f78623f2","title":"游仙窟诗 游后园","author":"崔五嫂","dynasty":"唐","verses":["极目游芳苑，相将对花林。","露净山光出，池鲜树影沈。","落花时泛酒，歌鸟或鸣琴。","是时日将夕，携樽就树阴。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-e062740a-1ef6-4155-97bb-1909c7f67109","tags":[]},{"id":"poem-75ab5d2be073309ab1081f05","title":"闻父讣二首  其一","author":"释了惠","dynasty":"宋","verses":["眉毛盖眼赤须胡，女嫁男婚不识渠。","唯是我侬偏孝顺，十年不作问安书。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-1a3339bf-13e8-418f-a70b-ec37d9f98968","tags":[]},{"id":"poem-75abe490ea279e496d3fc521","title":"送顾非熊作尉盱眙","author":"刘得仁","dynasty":"唐","verses":["一名兼一尉，未足是君伸。","厉数为诗者，多来作谏臣。","路翻平楚阔，草带古淮新。","天下虽云大，同声有几人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-32183dec-fbda-47f9-8dba-2726587dadb8","tags":[]},{"id":"poem-75b6c2252cbbf31e10c1af04","title":"前腔","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(生)我每年少正青春，更有武艺果超群。","我暂时落薄暂时贫，只得忍气吞声。","你如何只管打骂人？不学跨下韩信。","男儿有显达身荣日，果然一步跨青云。","(下)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8858","tags":[]},{"id":"poem-75b6e378047fae1c92aeee36","title":"诗一首","author":"张𬸦","dynasty":"唐","verses":["元来不相识，判自继知闻。","天公强多事，今遣若为分。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-9b1e453c-b38c-48d1-8b6e-08e5c0fb0f23","tags":[]},{"id":"poem-75c37202e256853b0c63748b","title":"蝶恋花·出塞","author":"纳兰性德","dynasty":"清","verses":["今古河山无定据。","画角声中，牧马频来去。","满目荒凉谁可语。","西风吹老丹枫树。","从前幽怨应无数。","铁马金戈，青冢黄昏路。","一往情深深几许。","深山夕照深秋雨。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-151","tags":[]},{"id":"poem-75cb1261fa22362f0b8e441f","title":"代陈季若上张帅  其一○","author":"林光朝","dynasty":"宋","verses":["南墙巨竹拂青烟，正在空斋簿领前。","欲向韩门借余润，乞将白璧种蓝田。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-78dd1520-a16e-489c-8f00-85febc806624","tags":[]},{"id":"poem-75d146d9c380e19befb12342","title":"同于秘丞赋瀑泉","author":"释延寿","dynasty":"宋","verses":["大禹不知凿，来源亦自成。","色应怜众白，声合让孤清。","远势曾吞海，飞流欲喷鲸。","灵槎如可泛，天际问归程。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-bac56787-3e55-4223-9870-a395dd117efd","tags":[]},{"id":"poem-75d61446895512ea1c6cdf16","title":"麟之趾","author":"佚名","dynasty":"先秦","verses":["麟之趾，振振公子，于嗟麟兮。","麟之定，振振公姓，于嗟麟兮。","麟之角，振振公族，于嗟麟兮。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-10","tags":[]},{"id":"poem-75d66a188005acea7d3a9217","title":"献淮南李相公","author":"赵嘏","dynasty":"唐","verses":["傅岩高静见台星，庙畧当时讨不庭。","万里有云归碧落，百川无浪到沧溟。","军中老将传兵术，江上诸侯受政经。","闻道国人思再入，镕金新铸鹤仪形。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-f8c6d737-9301-4233-91d1-2f031b753f08","tags":[]},{"id":"poem-75d6d1cf9984e8499a8c6d67","title":"愁坐","author":"赵文","dynasty":"宋","verses":["草色青青有底忙，空斋愁坐日偏长。","一春不作看花梦，满地苔痕煮药香。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-153b7d7c-b9ae-4e3f-bed8-d6e0fb50b9c3","tags":[]},{"id":"poem-75d86ab63ba8462bd9330d1c","title":"次韩机幕韵","author":"张栻","dynasty":"宋","verses":["韩杜有佳句，炯炯如辰星。","自昔此邦胜，中土亦饫听。","奇观今愈多，洞户长不扃。","秀色真可餐，腴泽到畦丁。","寒岩度轻舫，瘦岭著危亭。","固已小鴈荡，宁复谈锦屏。","自我来拥麾，每思御风泠。","如何半载间，足迹才一经。","居然俯仰中，便觉尘虑冥。","旧刻暗苍藓，往事过奔霆。","颇闻烟霞外，往往接神灵。","向来羽衣士，吐内夸奇龄。","终焉亦归尽，难留鬓毛青。","塞鴈度霄汉，沙鸥飞远汀。","大哉天壤间，逍遥各随形。","人生亦何有，泛若水上萍。","勿作分外念，但勉明德馨。","乘时各努力，日驭不我停。","梦回故园好，兰菊罗中庭。","从知靖节醉，远胜次公醒。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-caa51ae1-38cd-4412-8f1c-03888b9fd8bd","tags":[]},{"id":"poem-75d9c623768e0ab490fa1023","title":"相见欢·落花如梦凄迷","author":"纳兰性德","dynasty":"清","verses":["落花如梦凄迷，麝烟微，又是夕阳潜下小楼西。","愁无限，消瘦尽，有谁知。","闲教玉笼鹦鹉念郎诗。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-169","tags":[]},{"id":"poem-75df3896b1a7ab95d3b0d5e4","title":"咏史诗 赤壁","author":"胡曾","dynasty":"唐","verses":["烈火西焚魏帝旗，周郎开国虎争时。","交兵不假挥长剑，已挫英雄百万师。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-ae401595-6d59-4369-a3e6-c4709af78d2e","tags":[]},{"id":"poem-75e3d88c8283049e45f43bba","title":"颂古三十一首  其一七","author":"释安永","dynasty":"宋","verses":["快人一言，快马一鞭。","停囚长智，十万八千。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-76a56dbe-cdb1-43a2-987f-dc6008115f0e","tags":[]},{"id":"poem-75e7dd61a136a2cc88d7ad1b","title":"蝶恋花·一掬天和金粉腻","author":"欧阳修","dynasty":"宋","verses":["一掬天和金粉腻。","莲子心中，自有深深意。","意密莲深秋正媚。","将花寄恨无人会。","桥上少年桥下水。","小棹归时，不语牵红袂。","浪溅荷心圆又碎。","无端欲伴相思泪。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-777","tags":[]},{"id":"poem-75e9c2babe09587268179c1e","title":"田家","author":"赵崇嶓","dynasty":"宋","verses":["鸡豚白酒乐丰年，饱即高眠不问天。","少长有恩相尔汝，淳风应似伏羲前。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-66bcf66d-f769-43b4-b268-6adb81d2affa","tags":[]}];
